local config = {
  str_homestory_N26dianying_90060101_1_dialog_content = "Well, we're here. Whatever it is you're looking for should be in this classroom, yeah?",
  str_homestory_N26dianying_90060101_2_dialog_content = "Ahhh, what a great help.",
  str_homestory_N26dianying_90060101_3_dialog_content = "Not often you see such eager kids these days.",
  str_homestory_N26dianying_90060101_4_dialog_content = "What's with the flattery? Don't misunderstand, it's not like I really wanted to help, it's 'cuz I heard you say that everyone might be in danger...",
  str_homestory_N26dianying_90060101_5_dialog_content = "Everyone? Sounds grand, but I've got an inkling you're not being very honest.",
  str_homestory_N26dianying_90060101_6_dialog_content = "I suspect that you're mostly concerned about that girl.",
  str_homestory_N26dianying_90060101_7_dialog_content = "...",
  str_homestory_N26dianying_90060101_8_dialog_content = "A certain student council president, hmm?",
  str_homestory_N26dianying_90060101_9_dialog_content = "H-How'd you know?!",
  str_homestory_N26dianying_90060101_10_dialog_content = "Don't you underestimate the security department's intelligence.",
  str_homestory_N26dianying_90060101_11_dialog_content = "I bet there's an unsent love letter in your pocket.",
  str_homestory_N26dianying_90060101_12_dialog_content = "!!!",
  str_homestory_N26dianying_90060101_13_dialog_content = "Now now, I told you not to underestimate us.",
  str_homestory_N26dianying_90060101_14_dialog_content = "Alright young man, act natural now, or you'll let the cat out of the bag.",
  str_homestory_N26dianying_90060101_15_dialog_content = "No one would believe it anyway, even that student council president you like so much.",
  str_homestory_N26dianying_90060101_16_dialog_content = "Fine then. Guess it's best just to go along with you.",
  str_homestory_N26dianying_90060101_17_dialog_content = "Remember you said you'd protect her.",
  str_homestory_N26dianying_90060101_18_dialog_content = "Of course. We always honor our promises.",
  str_homestory_N26dianying_90060101_19_dialog_content = "As long as she's not the one we're after, that is.",
  str_homestory_N26dianying_90060101_20_dialog_content = "Let's go.",
  str_homestory_N26dianying_90060101_21_dialog_content = "Hey, what're you doing here, Kaseem?",
  str_homestory_N26dianying_90060101_22_dialog_content = "S-Student council president...?",
  str_homestory_N26dianying_90060101_23_dialog_content = "<size=30>Interesting. I didn't really expect her to be here. Well, that's suspicious...</size>",
  str_homestory_N26dianying_90060101_24_dialog_content = "<size=45>President! What are you doing here?</size>",
  str_homestory_N26dianying_90060101_25_dialog_content = "So I can check on the equipment for the upcoming school festival, obviously.",
  str_homestory_N26dianying_90060101_26_dialog_content = "The vice president and the student over there are helping too.",
  str_homestory_N26dianying_90060101_27_dialog_content = "<size=30>I think there's a strong possibility that the \"dangerous items\" have been hidden among the equipment.</size>",
  str_homestory_N26dianying_90060101_28_dialog_content = "<size=30>So what are you going to do?</size>",
  str_homestory_N26dianying_90060101_29_dialog_content = "Hmm... I don't recognize your friend here, is she from our school?",
  str_homestory_N26dianying_90060101_30_dialog_content = "She... doesn't seem to be from our school.",
  str_homestory_N26dianying_90060101_31_dialog_content = "Vice President...",
  str_homestory_N26dianying_90060101_32_dialog_content = "<size=30>Uh oh... Is she that overly cautious vice president?</size>",
  str_homestory_N26dianying_90060101_33_dialog_content = "<size=30>Despite appearances, it won't be easy to fool her, will it?</size>",
  str_homestory_N26dianying_90060101_34_dialog_content = "<size=30>Help me think of something, quick.</size>",
  str_homestory_N26dianying_90060101_35_dialog_content = "I'll try.",
  str_homestory_N26dianying_90060101_36_dialog_content = "She... She's...",
  str_homestory_N26dianying_90060101_37_option_content = "My girlfriend",
  str_homestory_N26dianying_90060101_38_dialog_content = "Your girlfriend! Be brave, just say it!",
  str_homestory_N26dianying_90060101_39_dialog_content = "S-She's my girlfriend!",
  str_homestory_N26dianying_90060101_40_dialog_content = "Er, don't you think that's a pretty dangerous choice, chubb.",
  str_homestory_N26dianying_90060101_41_dialog_content = "G-Girlfriend?!",
  str_homestory_N26dianying_90060101_42_dialog_content = "Since when?!",
  str_homestory_N26dianying_90060101_43_dialog_content = "<size=30>I didn't expect you to be interested in me, hehe...</size>",
  str_homestory_N26dianying_90060101_44_dialog_content = "<size=30>I didn't expect you to be interested in me! But I'm sorry, my heart already belongs to another.</size>",
  str_homestory_N26dianying_90060101_45_dialog_content = "<size=30>An outrageous claim like that only brings more attention!</size>",
  str_homestory_N26dianying_90060101_46_dialog_content = "<size=30>This kind of statement would only draw more attention at a time like this.</size>",
  str_homestory_N26dianying_90060101_47_dialog_content = "I-I'm sorry... Then, she's my...",
  str_homestory_N26dianying_90060101_48_option_content = "Cousin",
  str_homestory_N26dianying_90060101_49_dialog_content = "Just say she's your cousin! Be bold!",
  str_homestory_N26dianying_90060101_50_dialog_content = "Uh, this is my cousin. Really.",
  str_homestory_N26dianying_90060101_51_dialog_content = "They look nothing alike, chubb.",
  str_homestory_N26dianying_90060101_52_dialog_content = "Oh, your cousin! Won't you introduce us?",
  str_homestory_N26dianying_90060101_53_dialog_content = "Your cousin, is she? Won't you introduce us?",
  str_homestory_N26dianying_90060101_54_dialog_content = "Is it just me, or is this age gap a little off?",
  str_homestory_N26dianying_90060101_55_dialog_content = "I can't help but feel there's something a little off about the age gap.",
  str_homestory_N26dianying_90060101_56_dialog_content = "No, no. She's always looked mature for her age. She's looked like this since she was about eight.",
  str_homestory_N26dianying_90060101_57_dialog_content = "I-Is that so? That's really something...",
  str_homestory_N26dianying_90060101_58_dialog_content = "<size=30>What are you even saying?</size>",
  str_homestory_N26dianying_90060101_59_dialog_content = "<size=30>This just feels wrong... I'm starting to doubt the script...</size>",
  str_homestory_N26dianying_90060101_60_dialog_content = "<size=30>Won't this just draw even more attention towards me?</size>",
  str_homestory_N26dianying_90060101_61_dialog_content = "<size=30>Forget it, this just makes everyone focus on me even more.</size>",
  str_homestory_N26dianying_90060101_62_dialog_content = "I'm sorry...",
  str_homestory_N26dianying_90060101_63_option_content = "Neighbor",
  str_homestory_N26dianying_90060101_64_dialog_content = "Best just to say she's a neighbor. That's gotta be safe!",
  str_homestory_N26dianying_90060101_65_dialog_content = "S-She's my next-door neighbor.",
  str_homestory_N26dianying_90060101_66_dialog_content = "He's digging his own grave, chubb.",
  str_homestory_N26dianying_90060101_67_dialog_content = "Neighbor?",
  str_homestory_N26dianying_90060101_68_dialog_content = "Doesn't the student council president live next to you?",
  str_homestory_N26dianying_90060101_69_dialog_content = "President Theresa, do you recognize her?",
  str_homestory_N26dianying_90060101_70_dialog_content = "No... No I don't...",
  str_homestory_N26dianying_90060101_71_dialog_content = "Did you just move into the area?",
  str_homestory_N26dianying_90060101_72_dialog_content = "Oh, haha... I, I got it all wrong.",
  str_homestory_N26dianying_90060101_73_dialog_content = "<size=30>You're a real lost cause. Can't you think of something first before you open your mouth?</size>",
  str_homestory_N26dianying_90060101_74_dialog_content = "<size=30>I'm sorry! Let me think...</size>",
  str_homestory_N26dianying_90060101_75_dialog_content = "... Got it! I ran into her on my way here. She's an alumni of our school.",
  str_homestory_N26dianying_90060101_76_dialog_content = "She heard about our school festival and it reminded her of her time here, so she decided to come check it out.",
  str_homestory_N26dianying_90060101_77_dialog_content = "Ah I see. A former student, huh?",
  str_homestory_N26dianying_90060101_78_dialog_content = "So that's why she looks older.",
  str_homestory_N26dianying_90060101_79_dialog_content = "(Good job, kid. We seem to have fooled her for now.)",
  str_homestory_N26dianying_90060101_80_dialog_content = "The equipment's all been checked, President.",
  str_homestory_N26dianying_90060101_81_dialog_content = "Thanks, mister.",
  str_homestory_N26dianying_90060101_82_dialog_content = "\"Mister\"? A boy? Is she suddenly cross casting the role?",
  str_homestory_N26dianying_90060101_83_dialog_content = "Bethel seems to be trying something new.",
  str_homestory_N26dianying_90060101_84_dialog_content = "Well then please, feel free to look around. Let us know if you have any suggestions.",
  str_homestory_N26dianying_90060101_85_dialog_content = "Excellent! I'll have a look around and see if I can offer any advice from a grownup's perspective!",
  str_homestory_N26dianying_90060101_86_dialog_content = "What's that, President?!",
  str_homestory_N26dianying_90060101_87_dialog_content = "This is... an ordinary new fryer?",
  str_homestory_N26dianying_90060101_88_dialog_content = "That's the appliance that fries food without needing oil, right?",
  str_homestory_N26dianying_90060101_89_dialog_content = "Indeed. It's super trendy nowadays.",
  str_homestory_N26dianying_90060101_90_dialog_content = "<size=30>I see... It seems really easy to hide certain \"things\" inside the frying basket.</size>",
  str_homestory_N26dianying_90060101_91_dialog_content = "<size=30>Certain \"mechanisms\" could also hypothetically be triggered by heat.</size>",
  str_homestory_N26dianying_90060101_92_dialog_content = "<size=30>Certain \"mechanisms\" could also hypothetically be triggered by heat. Best to look inside.</size>",
  str_homestory_N26dianying_90060101_93_dialog_content = "It doesn't look great for cooking, to be honest.",
  str_homestory_N26dianying_90060101_94_dialog_content = "Oh, this is just a prop provided by our cosplay club.",
  str_homestory_N26dianying_90060101_95_dialog_content = "Didn't the... something Alchemy Factory make this?",
  str_homestory_N26dianying_90060101_96_dialog_content = "Theresa's Alchemy Factory?",
  str_homestory_N26dianying_90060101_97_dialog_content = "Very funny.",
  str_homestory_N26dianying_90060101_98_dialog_content = "...",
  str_homestory_N26dianying_90060101_99_dialog_content = "(You want me to check inside? Can we do that?)",
  str_homestory_N26dianying_90060101_100_dialog_content = "That's my special dish!",
  str_homestory_N26dianying_90060101_101_dialog_content = "A very good friend gave me the recipe. It's beetroot soup.",
  str_homestory_N26dianying_90060101_102_dialog_content = "It's refreshing and nourishing for the soul.",
  str_homestory_N26dianying_90060101_103_dialog_content = "Beetroot soup... Do you mean...",
  str_homestory_N26dianying_90060101_104_dialog_content = "Oh, you must've had my friend's beetroot soup before, Kaseem.",
  str_homestory_N26dianying_90060101_105_dialog_content = "I... I don't know.",
  str_homestory_N26dianying_90060101_106_dialog_content = "This isn't a great conversation, however you look at it, so let's change the topic.",
  str_homestory_N26dianying_90060101_107_dialog_content = "...",
  str_homestory_N26dianying_90060101_108_dialog_content = "(You want to check the soup...? Really? Actually, it is pretty dangerous.)",
  str_homestory_N26dianying_90060101_108X1_dialog_content = "Hmm... It seems a little vacant here.",
  str_homestory_N26dianying_90060101_108X2_dialog_content = "Maybe they are still getting things ready?",
  str_homestory_N26dianying_90060101_108X3_dialog_content = "It's possible, but I smell the scent of danger nearby.",
  str_homestory_N26dianying_90060101_109_dialog_content = "Huh? What did you say?",
  str_homestory_N26dianying_90060101_110_dialog_content = "Nothing. You keep doing your thing, I'll just have a little look around.",
  str_homestory_N26dianying_90060101_111_dialog_content = "Oh... Okay.",
  str_homestory_N26dianying_90060101_112_dialog_content = "By the way, Kaseem, how are the other preparations for the festival coming along?",
  str_homestory_N26dianying_90060101_113_dialog_content = "Ah, well, the sports field...",
  str_homestory_N26dianying_90060101_114_dialog_content = "Hey! You're being too obvious. Everyone can see you sneaking about like that!",
  str_homestory_N26dianying_90060101_115_dialog_content = "...",
  str_homestory_N26dianying_90060101_116_dialog_content = "(What? You want me to find a way to buy us more time? What, like have some kind of detector hidden in the mask to sniff out dangerous articles?)",
  str_homestory_N26dianying_90060101_117_dialog_content = "(What? You want me to find a way to buy us more time? What, like have some kind of detector hidden in the pocket to look for dangerous articles?)",
  str_homestory_N26dianying_90060101_118_dialog_content = "(How can you convey so much just with your eyes?)",
  str_homestory_N26dianying_90060101_119_dialog_content = "(Actually, how come I can know what you mean so clearly?!)",
  str_homestory_N26dianying_90060101_120_dialog_content = "Drat... Need to cover her somehow...",
  str_homestory_N26dianying_90060101_121_dialog_content = "What's the matter, Kaseem? Is something wrong with your eyes?",
  str_homestory_N26dianying_90060101_122_dialog_content = "Oh, Miss President, I...",
  str_homestory_N26dianying_90060101_123_option_content = "Let's sing!",
  str_homestory_N26dianying_90060101_123_dialog_content = "There's no time! Use your voice to attract its attention!",
  str_homestory_N26dianying_90060101_124_dialog_content = "I wanna sing you the song for the campus festival!",
  str_homestory_N26dianying_90060101_125_dialog_content = "Huh?",
  str_homestory_N26dianying_90060101_126_dialog_content = "I've been secretly practicing this song from the radio. And I've put in much effort, so listen up!",
  str_homestory_N26dianying_90060101_127_dialog_content = "I'm actually an awesome singer, just watch me hit all the high notes!",
  str_homestory_N26dianying_90060101_128_dialog_content = "Ohh? You're gonna sing? Then I'll do the harmony!",
  str_homestory_N26dianying_90060101_129_dialog_content = "Ohh? You're gonna sing? Lemme accompany you with these bells.",
  str_homestory_N26dianying_90060101_130_dialog_content = "Sudden bursting into song like a moron.",
  str_homestory_N26dianying_90060101_131_dialog_content = "What a moron... Suddenly bursting into song.",
  str_homestory_N26dianying_90060101_132_dialog_content = "We still have a lot to prepare!",
  str_homestory_N26dianying_90060101_133_dialog_content = "We still have a lot to prepare.",
  str_homestory_N26dianying_90060101_134_option_content = "Please return the videotape!",
  str_homestory_N26dianying_90060101_134_dialog_content = "You remembered the video all of a sudden!",
  str_homestory_N26dianying_90060101_135_dialog_content = "President!",
  str_homestory_N26dianying_90060101_136_dialog_content = "Hmm?",
  str_homestory_N26dianying_90060101_137_dialog_content = "Can you return the video I lent you?!",
  str_homestory_N26dianying_90060101_138_dialog_content = "Huh? You only lent it to me yesterday!",
  str_homestory_N26dianying_90060101_139_dialog_content = "And you agreed to lend me \"Cloud Island Ultra Warrior: The General\" for a week...",
  str_homestory_N26dianying_90060101_140_dialog_content = "And now you suddenly need it back?",
  str_homestory_N26dianying_90060101_141_dialog_content = "Actually... I forgot there was another video in the case... Something not for girls to see!",
  str_homestory_N26dianying_90060101_142_dialog_content = "The content of \"Railway Warrior Bros\" is far too bloody!",
  str_homestory_N26dianying_90060101_143_dialog_content = "Oh, I-I see...",
  str_homestory_N26dianying_90060101_144_dialog_content = "Listen, I'll bring over the right one a little bit later.",
  str_homestory_N26dianying_90060101_145_option_content = "Waffle!",
  str_homestory_N26dianying_90060101_145_dialog_content = "Whoa there! This film is for people of all ages. Look at the scale!",
  str_homestory_N26dianying_90060101_146_dialog_content = "President Theresa!",
  str_homestory_N26dianying_90060101_147_dialog_content = "Hmm?",
  str_homestory_N26dianying_90060101_148_dialog_content = "What's your type...?",
  str_homestory_N26dianying_90060101_149_dialog_content = "W-Why would you suddenly ask me that??",
  str_homestory_N26dianying_90060101_150_dialog_content = "I-If you insist... You...",
  str_homestory_N26dianying_90060101_151_dialog_content = "You fool! Why would I talk about that sort of thing in front of so many people?!",
  str_homestory_N26dianying_90060101_152_dialog_content = "Ahem... That's a little bit out of order, Kaseem.",
  str_homestory_N26dianying_90060101_153_dialog_content = "Uh... Need me to excuse you?",
  str_homestory_N26dianying_90060101_154_dialog_content = "Is this what the book calls a line drive?",
  str_homestory_N26dianying_90060101_155_dialog_content = "No need!",
  str_homestory_N26dianying_90060101_155X1_dialog_content = "What are you talking about, Kaseem!?",
  str_homestory_N26dianying_90060101_156_dialog_content = "Well, really! What do you think, senior, is it just me, or is Kaseem acting really odd today?",
  str_homestory_N26dianying_90060101_157_dialog_content = "Huh? Senior? What're you looking for over there?",
  str_homestory_N26dianying_90060101_158_dialog_content = "Oops, looks like I've been rumbled.",
  str_homestory_N26dianying_90060101_159_dialog_content = "Nothing for it but to start my investigation over... With this flashing pen that erases memories!",
  str_homestory_N26dianying_90060101_160_dialog_content = "Nothing for it but to start again, with this wrench that erases memories...!",
  str_homestory_N26dianying_90060101_161_dialog_content = "Is this a vending machine, Miss President?",
  str_homestory_N26dianying_90060101_162_dialog_content = "Uh, yeah.",
  str_homestory_N26dianying_90060101_163_dialog_content = "I thought people might want a drink to go with their snacks.",
  str_homestory_N26dianying_90060101_164_dialog_content = "So I found a way to borrow one especially.",
  str_homestory_N26dianying_90060101_165_dialog_content = "Wow, that's pretty impressive. No wonder you're the President.",
  str_homestory_N26dianying_90060101_166_dialog_content = "I'm the one who hauled it all the way here!",
  str_homestory_N26dianying_90060101_167_dialog_content = "...",
  str_homestory_N26dianying_90060101_168_dialog_content = "(Eye signals again... Huh? Has that area been checked? No dangerous articles?)",
  str_homestory_N26dianying_90060101_169_dialog_content = "(Keep stalling... That vending machine is super suspicious, it's stocked with loads of drinks I've never even seen before!)",
  str_homestory_N26dianying_90060101_170_dialog_content = "(Fish mint flavor milk? Rust pop? Vegetable juice?)",
  str_homestory_N26dianying_90060101_171_dialog_content = "(Is now really the time to wonder about that?! I'm kinda at the end of my tether here!)",
  str_homestory_N26dianying_90060101_172_dialog_content = "(And what vegetable exactly is the juice made from? It's not like some weird tea, is it?)",
  str_homestory_N26dianying_90060101_173_dialog_content = "Just gotta keep going...",
  str_homestory_N26dianying_90060101_174_dialog_content = "Is this a drum kit, Miss President?",
  str_homestory_N26dianying_90060101_175_dialog_content = "Yep, sure is.",
  str_homestory_N26dianying_90060101_176_dialog_content = "Some departments are going to put on a concert for the festival, so they've left that here for now.",
  str_homestory_N26dianying_90060101_177_dialog_content = "I see.",
  str_homestory_N26dianying_90060101_178_dialog_content = "...",
  str_homestory_N26dianying_90060101_179_dialog_content = "(The sort of things we're looking for could be concealed inside the drums. Should we tear them open?)",
  str_homestory_N26dianying_90060101_180_dialog_content = "(Wait a while. If they're torn, then they'll be useless!)",
  str_homestory_N26dianying_90060101_182_dialog_content = "A turkey, Miss President?",
  str_homestory_N26dianying_90060101_183_dialog_content = "Why does the festival need turkey?",
  str_homestory_N26dianying_90060101_184_dialog_content = "Oh, that's a student's cat... But I have no idea where it got the turkey from...",
  str_homestory_N26dianying_90060101_185_dialog_content = "Oh, right. You know, I once had a cat that helped me work.",
  str_homestory_N26dianying_90060101_186_dialog_content = "...",
  str_homestory_N26dianying_90060101_187_dialog_content = "(What? Something could be hidden inside the turkey? You wanna investigate without ruining it?)",
  str_homestory_N26dianying_90060101_188_dialog_content = "(Is that... even possible? If you manage it, you've gotta teach me how.)",
  str_homestory_N26dianying_90060101_188X1_dialog_content = "It's empty...",
  str_homestory_N26dianying_90060101_188X2_dialog_content = "Is this really to prepare for a campus festival?",
  str_homestory_N26dianying_90060101_188X3_dialog_content = "It really is unusual. There was something here before.",
  str_homestory_N26dianying_90060101_188X4_dialog_content = "This is very suspicious. I need to investigate it carefully!",
  str_homestory_N26dianying_90060101_188X5_dialog_content = "Cover me!",
  str_homestory_N26dianying_90060101_188X6_dialog_content = "Huh? But there's no cover here at all!",
  str_homestory_N26dianying_90060101_190_option_content = "Dance!",
  str_homestory_N26dianying_90060101_190_dialog_content = "Quickly, use the move you have been practicing for a long time!",
  str_homestory_N26dianying_90060101_191_dialog_content = "Forget it!",
  str_homestory_N26dianying_90060101_192_dialog_content = "Everyone, please watch—!",
  str_homestory_N26dianying_90060101_193_dialog_content = "My amazing, wonderful dance!",
  str_homestory_N26dianying_90060101_193X1_dialog_content = "Is this move the legendary planet walk dance? Chubb!",
  str_homestory_N26dianying_90060101_194_dialog_content = "Aaah...!!",
  str_homestory_N26dianying_90060101_195_dialog_content = "Kaseem, today you're really...",
  str_homestory_N26dianying_90060101_196_dialog_content = "Excitable!",
  str_homestory_N26dianying_90060101_197_dialog_content = "Oh? Thanks!",
  str_homestory_N26dianying_90060101_198_dialog_content = "(Does she actually like me like this?)",
  str_homestory_N26dianying_90060101_199_dialog_content = "How dumb...",
  str_homestory_N26dianying_90060101_200_dialog_content = "You've, like, lost your mind...",
  str_homestory_N26dianying_90060101_201_dialog_content = "There's something really weird going on with you today.",
  str_homestory_N26dianying_90060101_202_dialog_content = "Awesome! Can you teach me how to dance, please!",
  str_homestory_N26dianying_90060101_203_option_content = "Palm read?",
  str_homestory_N26dianying_90060101_203_dialog_content = "Quickly, use the knowledge you learned from books...!",
  str_homestory_N26dianying_90060101_203X1_dialog_content = "Yes! Recall the points mentioned in the book \"Getting Close to your Enemies Quickly\" now...",
  str_homestory_N26dianying_90060101_203X2_dialog_content = "It's obvious from the title of the book that there are many problems with it, chubb!",
  str_homestory_N26dianying_90060101_204_dialog_content = "Allow me to read your fortunes in your palms!",
  str_homestory_N26dianying_90060101_205_dialog_content = "I'm sorry... I can't accept that, even as a conversation filler.",
  str_homestory_N26dianying_90060101_206_dialog_content = "Are you an idiot? Better to let me read your palm!",
  str_homestory_N26dianying_90060101_207_dialog_content = "While we're at it, let me make sure your lifeline ends today.",
  str_homestory_N26dianying_90060101_208_dialog_content = "Sure, and I'll just confirm that your lifeline does indeed end today.",
  str_homestory_N26dianying_90060101_209_dialog_content = "Well, really! What do you think, senior, is it just me, or is Kaseem acting really odd today?",
  str_homestory_N26dianying_90060101_210_dialog_content = "Huh? Senior? What're you looking for over there?",
  str_homestory_N26dianying_90060101_211_dialog_content = "Oops, looks like I've been rumbled.",
  str_homestory_N26dianying_90060101_212_dialog_content = "Nothing for it but to start again, with this pen that erases memories...!",
  str_homestory_N26dianying_90060101_213_dialog_content = "Nothing for it but to start again, with this wrench that erases memories...!",
  str_homestory_N26dianying_90060101_214_option_content = "UFO?",
  str_homestory_N26dianying_90060101_214_dialog_content = "Extremely traditional methods are usually the most effective!",
  str_homestory_N26dianying_90060101_215_dialog_content = "Over there! A UFO!",
  str_homestory_N26dianying_90060101_216_dialog_content = "Quick, look!",
  str_homestory_N26dianying_90060101_217_dialog_content = "UFO! Over there!",
  str_homestory_N26dianying_90060101_218_dialog_content = "...",
  str_homestory_N26dianying_90060101_219_dialog_content = "...",
  str_homestory_N26dianying_90060101_220_dialog_content = "...",
  str_homestory_N26dianying_90060101_220X1_dialog_content = "...",
  str_homestory_N26dianying_90060101_221_dialog_content = "Well, really. Would you look at him, senior? Kaseem is acting really strangely today.",
  str_homestory_N26dianying_90060101_222_dialog_content = "Huh? Senior? What're you looking for over there?",
  str_homestory_N26dianying_90060101_223_dialog_content = "Oops, looks like I've been rumbled.",
  str_homestory_N26dianying_90060101_224_dialog_content = "Nothing for it but to start again, with this pen that erases memories...!",
  str_homestory_N26dianying_90060101_225_dialog_content = "Nothing for it but to start again, with this wrench that erases memories...!",
  str_homestory_N26dianying_90060101_226_dialog_content = "...",
  str_homestory_N26dianying_90060101_227_dialog_content = "(Finished checking over here, and still nothing?)",
  str_homestory_N26dianying_90060101_228_dialog_content = "What's this, Miss President?",
  str_homestory_N26dianying_90060101_229_dialog_content = "Oh! I forgot to say.",
  str_homestory_N26dianying_90060101_230_dialog_content = "This is the highlight of the festival!",
  str_homestory_N26dianying_90060101_231_dialog_content = "Just pull here, and the machine lays an egg.",
  str_homestory_N26dianying_90060101_232_dialog_content = "There are loads of different, tasty dishes inside each egg. It's a wonderful contraption!",
  str_homestory_N26dianying_90060101_233_dialog_content = "When did we get such an awesome machine...?",
  str_homestory_N26dianying_90060101_234_dialog_content = "Our very kind student donated it. Apparently, it's pretty expensive.",
  str_homestory_N26dianying_90060101_235_dialog_content = "Good things should be shared with everyone, heheh.",
  str_homestory_N26dianying_90060101_236_dialog_content = "Everyone's favorite things are inside, heheh.",
  str_homestory_N26dianying_90060101_237_dialog_content = "Maybe we should take the opportunity to test it again, and give Kaseem and our senior a chance to see just how incredible it is.",
  str_homestory_N26dianying_90060101_238_dialog_content = "<size=30>This contraption is suspicious and the last place where something dangerous could be hidden. We should seize this chance.</size>",
  str_homestory_N26dianying_90060101_239_dialog_content = "<size=30>Got it. Don't worry.</size>",
  str_homestory_N26dianying_90060101_240_dialog_content = "Then, please...",
  str_homestory_N26dianying_90060101_243_dialog_content = "<size=30>How is it possible... Did we receive bad intelligence?</size>",
  str_homestory_N26dianying_90060101_244_dialog_content = "<size=30>So, what do we do?</size>",
  str_homestory_N26dianying_90060101_245_dialog_content = "<size=30>Let's get out of here for now. I might be rumbled if we stay too much longer.</size>",
  str_homestory_N26dianying_90060101_246_dialog_content = "Ah, I still have things to do. I'm afraid I need to get going.",
  str_homestory_N26dianying_90060101_247_dialog_content = "I wish you all the best for your campus festival.",
  str_homestory_N26dianying_90060101_248_dialog_content = "Ah, okay. Thank you, senior.",
  str_homestory_N26dianying_90060101_249_dialog_content = "Leaving, just like that? There's something fishy about this senior.",
  str_homestory_N26dianying_90060101_250_dialog_content = "...",
  str_homestory_N26dianying_90060101_251_option_content = "The President operates it",
  str_homestory_N26dianying_90060101_252_dialog_content = "Let the leading lady do it!",
  str_homestory_N26dianying_90060101_253_dialog_content = "Would the President like to operate it?",
  str_homestory_N26dianying_90060101_254_dialog_content = "Really want the President to do it? Haven't you forgotten something important, chubb?",
  str_homestory_N26dianying_90060101_255_dialog_content = "Fine then, I'll make a fool of myself.",
  str_homestory_N26dianying_90060101_256_dialog_content = "Hrrrnnnng—!",
  str_homestory_N26dianying_90060101_257_dialog_content = "Ha! I didn't really think there'd be an egg.",
  str_homestory_N26dianying_90060101_258_dialog_content = "Looks like a normal egg...",
  str_homestory_N26dianying_90060101_259_dialog_content = "There's tiramisu inside.",
  str_homestory_N26dianying_90060101_260_dialog_content = "Could the intelligence have been wrong? Nothing for it but to keep looking.",
  str_homestory_N26dianying_90060101_261_option_content = "Operate it yourself",
  str_homestory_N26dianying_90060101_262_dialog_content = "Let me do it. At least you'll be reassured.",
  str_homestory_N26dianying_90060101_263_dialog_content = "I'll do it!",
  str_homestory_N26dianying_90060101_264_dialog_content = "Just pull here, right?",
  str_homestory_N26dianying_90060101_265_dialog_content = "Yep.",
  str_homestory_N26dianying_90060101_266_dialog_content = "Done!",
  str_homestory_N26dianying_90060101_267_dialog_content = "It's flashing, and there seems to be a mille-feuille inside?",
  str_homestory_N26dianying_90060101_268_dialog_content = "<color=#e8d9bb>Beep—Beep—</color>",
  str_homestory_N26dianying_90060101_269_dialog_content = "Wait! What's this?!",
  str_homestory_N26dianying_90060101_270_dialog_content = "Drat, discovered! Then I'll have you all—!",
  str_homestory_N26dianying_90060101_271_dialog_content = "What's going on?!",
  str_homestory_N26dianying_90060101_272_dialog_content = "What's going on? I've been waiting all night for the climax, chubb!",
  str_homestory_N26dianying_90060101_273_option_content = "Invite the senior",
  str_homestory_N26dianying_90060101_274_dialog_content = "Hmm, she's brought a device for detecting dangerous objects, so maybe it's safest to let the senior check.",
  str_homestory_N26dianying_90060101_275_dialog_content = "Would the senior like to try?",
  str_homestory_N26dianying_90060101_275X1_dialog_content = "Hmm, you look a little smarter, chubb!",
  str_homestory_N26dianying_90060101_276_dialog_content = "Oh, wise choice. Sure, I'll give it a go.",
  str_homestory_N26dianying_90060101_277_dialog_content = "This egg has a tasty treat inside?",
  str_homestory_N26dianying_90060101_278_dialog_content = "I think it's a black forest gateau inside.",
  str_homestory_N26dianying_90060101_279_dialog_content = "(Huh? My detector's reacting.)",
  str_homestory_N26dianying_90060101_280_dialog_content = "Nobody move! I'm with the security department!",
  str_homestory_N26dianying_90060101_281_dialog_content = "Here's my badge. Now, I'm gonna bring everyone in for questioning.",
  str_homestory_N26dianying_90060101_282_dialog_content = "Senior?",
  str_homestory_N26dianying_90060101_283_dialog_content = "Drat, discovered! Then I'll have you all—!",
  str_homestory_N26dianying_90060101_284_dialog_content = "Eh? What are you doing, unfamiliar enthusiastic student?",
  str_homestory_N26dianying_90060101_285_dialog_content = "Huh? What? Why's the controller not working?",
  str_homestory_N26dianying_90060101_286_dialog_content = "Huh? What? Why's the controller not working? Did the props department not take good care of it?",
  str_homestory_N26dianying_90060101_287_dialog_content = "Too gullible, the detector in my mask has a small-range jammer.",
  str_homestory_N26dianying_90060101_288_dialog_content = "Too gullible, my detector has a small-range jammer.",
  str_homestory_N26dianying_90060101_289_dialog_content = "Damn... As soon as it's activated, the whole school will turn into candy, just like those candy houses in fairy tales!",
  str_homestory_N26dianying_90060101_290_dialog_content = "I could escape by hiding inside a chocolate wall...",
  str_homestory_N26dianying_90060101_291_dialog_content = "If possible, I'd want to fly away on a chocolate ship.",
  str_homestory_N26dianying_90060101_292_dialog_content = "... Then, then blood sugar levels will be too high... No! It's too dangerous!",
  str_homestory_N26dianying_90060101_293_dialog_content = "I've been watching your Carbohydrate Empire for a while now, so you'd all better come quietly.",
  str_homestory_N26dianying_90060101_294_dialog_content = "I've been watching your Sugar Kingdom for a while now, so you'd all better come quietly.",
  str_homestory_N26dianying_90060101_295_dialog_content = "You think you'll take me so easily?",
  str_homestory_N26dianying_90060101_296_dialog_content = "Huh? I can't move!",
  str_homestory_N26dianying_90060101_297_dialog_content = "Ugh...!",
  str_homestory_N26dianying_90060101_298_dialog_content = "P-President...!",
  str_homestory_N26dianying_90060101_299_dialog_content = "You...! Enthusiastic student!",
  str_homestory_N26dianying_90060101_300_dialog_content = "You were lucky this time. I guess I'll have to use the ace up my sleeve.",
  str_homestory_N26dianying_90060101_301_dialog_content = "But our noble dream of addicting people to sugar will not be extinguished!",
  str_homestory_N26dianying_90060101_302_dialog_content = "We'll see!",
  str_homestory_N26dianying_90060101_303_dialog_content = "No... I won't let you go...",
  str_homestory_N26dianying_90060101_304_dialog_content = "Vice-President?!",
  str_homestory_N26dianying_90060101_305_dialog_content = "Think you can cause such a fuss at the campus festival, and then just leave so easily?",
  str_homestory_N26dianying_90060101_306_dialog_content = "What?! How come you can move?",
  str_homestory_N26dianying_90060101_307_dialog_content = "What?! How come you can move? Director! This isn't right!",
  str_homestory_N26dianying_90060101_308_dialog_content = "Who interfered with our equipment? Your security department would never be able to pull this off, so WHO WAS IT?!",
  str_homestory_N26dianying_90060101_309_dialog_content = "Take this!",
  str_homestory_N26dianying_90060101_310_dialog_content = "Hand over all the desserts!",
  str_homestory_N26dianying_90060101_311_dialog_content = "The guy who wanted to get everyone hooked on sugar at the festival has been taken away.",
  str_homestory_N26dianying_90060101_312_dialog_content = "Oh... And there I was, thinking he was really just a keen student.",
  str_homestory_N26dianying_90060101_313_dialog_content = "I've recovered all the desserts too.",
  str_homestory_N26dianying_90060101_314_dialog_content = "Anyway, at least peace has returned to the campus.",
  str_homestory_N26dianying_90060101_315_dialog_content = "Of course! This is our campus, after all.",
  str_homestory_N26dianying_90060101_316_dialog_content = "It's not just that senior from the security department. Many people are looking out for it, too.",
  str_homestory_N26dianying_90060201_1_dialog_content = "Oh dear, I'm already late! I just hope the contact hasn't left yet...",
  str_homestory_N26dianying_90060201_2_dialog_content = "Pardon me sir, but is this the Thorngate Inn?",
  str_homestory_N26dianying_90060201_3_dialog_content = "Indeed it is.",
  str_homestory_N26dianying_90060201_4_dialog_content = "We serve all kinds of food here, perfect for a weary traveler.",
  str_homestory_N26dianying_90060201_5_dialog_content = "Not to mention a few drinks you won't find anywhere else in the world.",
  str_homestory_N26dianying_90060201_6_dialog_content = "Why not stay a while and sample my wares?",
  str_homestory_N26dianying_90060201_7_dialog_content = "My inn may not look like much, but our dishes have won contests all throughout the kingdom.",
  str_homestory_N26dianying_90060201_8_dialog_content = "See? Over there is our biggest trophy yet.",
  str_homestory_N26dianying_90060201_9_dialog_content = "That sure is an interesting trophy...",
  str_homestory_N26dianying_90060201_10_dialog_content = "We also have a number of sandbags scattered throughout the inn.",
  str_homestory_N26dianying_90060201_11_dialog_content = "If you want, you can stretch your legs for a while.",
  str_homestory_N26dianying_90060201_12_dialog_content = "What's this sort of thing doing in an inn...?",
  str_homestory_N26dianying_90060201_13_dialog_content = "Well, the inn does look fairly clean... Yes, I think I'll stay for a while.",
  str_homestory_N26dianying_90060201_14_dialog_content = "There's an empty seat right over there. Make yourself at home, friend.",
  str_homestory_N26dianying_90060201_15_dialog_content = "This place does pretty well for itself...",
  str_homestory_N26dianying_90060201_16_dialog_content = "It's not even mealtime, yet the inn is full of customers!",
  str_homestory_N26dianying_90060201_17_dialog_content = "In any case, I'm here to see an old acquaintance, so I won't need my own table.",
  str_homestory_N26dianying_90060201_18_dialog_content = "Well, the style looks out of place here.",
  str_homestory_N26dianying_90060201_19_dialog_content = "Did the innkeeper buy it while traveling in a foreign country?",
  str_homestory_N26dianying_90060201_20_dialog_content = "In any case, I'm here to see an old acquaintance, so I won't need my own table.",
  str_homestory_N26dianying_90060201_21_dialog_content = "Now, that's just going too far...",
  str_homestory_N26dianying_90060201_22_dialog_content = "I don't think a quilt is really necessary, even if it is a little cold out!",
  str_homestory_N26dianying_90060201_23_dialog_content = "In any case, I'm here to see an old acquaintance, so I won't need my own table.",
  str_homestory_N26dianying_90060201_23X1_dialog_content = "It's a pity that the shop is still being renovated... There aren't even any tables or chairs.",
  str_homestory_N26dianying_90060201_23X2_dialog_content = "Since you're the only guest, you can eat standing right at the counter.",
  str_homestory_N26dianying_90060201_23X3_dialog_content = "What? You think I can reach the counter!?",
  str_homestory_N26dianying_90060201_23X4_dialog_content = "I don't know what to do, either. All I can do is ask you to try to be taller.",
  str_homestory_N26dianying_90060201_23X5_dialog_content = "Don't you think I'm a little too old to keep growing taller!?",
  str_homestory_N26dianying_90060201_23X6_dialog_content = "Besides, there really is no one here! Am I in the right place?",
  str_homestory_N26dianying_90060201_23X7_dialog_content = "Drat! Search around here again. Maybe there's another Thorngate Inn.",
  str_homestory_N26dianying_90060201_23X8_dialog_content = "...",
  str_homestory_N26dianying_90060201_24_dialog_content = "Oh, I see. Do as you wish, then.",
  str_homestory_N26dianying_90060201_25_dialog_content = "Right, now let's go over the quest one more time...",
  str_homestory_N26dianying_90060201_26_dialog_content = "\"Go to the Thorngate Inn and make contact with the mysterious warrior.\"",
  str_homestory_N26dianying_90060201_27_dialog_content = "\"Secrecy is of the utmost importance, so the warrior has chosen to keep their identity hidden.\"",
  str_homestory_N26dianying_90060201_28_dialog_content = "\"Just know that the warrior in question is in the prime of their life and that their martial arts are second to none.\"",
  str_homestory_N26dianying_90060201_29_dialog_content = "\"Once at the Thorngate Inn, order a pot of osmanthus wine, and the warrior will approach you.\"",
  str_homestory_N26dianying_90060201_30_dialog_content = "\"After you make contact, hand them the elixir in your possession, and the world will be at peace once more.\"",
  str_homestory_N26dianying_90060201_31_dialog_content = "\"Best of luck, courageous hero!\"",
  str_homestory_N26dianying_90060201_32_dialog_content = "Simple enough! I just have to find the right person, and my quest is complete!",
  str_homestory_N26dianying_90060201_33_dialog_content = "Now let's see which of the guests is the warrior I'm searching for...",
  str_homestory_N26dianying_90060201_34_dialog_content = "Oh! O-Over there!",
  str_homestory_N26dianying_90060201_35_dialog_content = "Dressed in all black, with a solemn, reserved demeanor... A master warrior trying to keep a low profile!",
  str_homestory_N26dianying_90060201_36_dialog_content = "She must be the person I'm looking for! Now for the next step!",
  str_homestory_N26dianying_90060201_37_dialog_content = "Innkeeper! A pot of your finest osmanthus wine, please!",
  str_homestory_N26dianying_90060201_38_dialog_content = "Coming right up! I'll just leave this here for you.",
  str_homestory_N26dianying_90060201_39_dialog_content = "Not many folks drink this nowadays, but please enjoy.",
  str_homestory_N26dianying_90060201_40_dialog_content = "That's perfectly fine. Some things should be kept a \"secret,\" right?",
  str_homestory_N26dianying_90060201_41_dialog_content = "Pardon me, but would you care to have a drink with me?",
  str_homestory_N26dianying_90060201_42_dialog_content = "... No. Now go away.",
  str_homestory_N26dianying_90060201_43_dialog_content = "But it's a pot of osmanthus wine! Osmanthus! Not a lot of people know about it, you know?",
  str_homestory_N26dianying_90060201_44_dialog_content = "Besides... You look like the type of person who likes this kind of drink! Right? Right???",
  str_homestory_N26dianying_90060201_45_dialog_content = "... Who are you to tell me my own preferences?",
  str_homestory_N26dianying_90060201_46_dialog_content = "Better yet... Who are you, anyway?",
  str_homestory_N26dianying_90060201_47_dialog_content = "Shh! I'll tell you, but keep it down...",
  str_homestory_N26dianying_90060201_48_dialog_content = "The truth is, I know who you really are...",
  str_homestory_N26dianying_90060201_49_dialog_content = "You do?!",
  str_homestory_N26dianying_90060201_50_dialog_content = "W-Wait! Just keep calm, okay?",
  str_homestory_N26dianying_90060201_51_dialog_content = "If you know who I am... Then I cannot allow you to live.",
  str_homestory_N26dianying_90060201_52_dialog_content = "What? No! I mean I know that you're keeping your identity a secret! It's because your quest is of the utmost importance, remember?",
  str_homestory_N26dianying_90060201_53_dialog_content = "I'm here to help you!",
  str_homestory_N26dianying_90060201_54_dialog_content = "Help me...?",
  str_homestory_N26dianying_90060201_55_dialog_content = "With what, might I ask?",
  str_homestory_N26dianying_90060201_56_dialog_content = "I know your martial arts are second to none in the world, and that you're in the prime of your life...",
  str_homestory_N26dianying_90060201_57_dialog_content = "But in order to protect the world, there's one more thing that you require.",
  str_homestory_N26dianying_90060201_58_dialog_content = "... What the devil are you talking about?",
  str_homestory_N26dianying_90060201_59_dialog_content = "The elixir, of course! I have it right here, just for you!",
  str_homestory_N26dianying_90060201_60_dialog_content = "R-Really?!",
  str_homestory_N26dianying_90060201_61_dialog_content = "Could this truly be happening...?",
  str_homestory_N26dianying_90060201_62_dialog_content = "That's right! Sorry if I was late.",
  str_homestory_N26dianying_90060201_63_dialog_content = "That's fine! Just hand it over already!",
  str_homestory_N26dianying_90060201_64_dialog_content = "With this poison, I can finally assassinate the island's ruler and bring peace to the world once again!",
  str_homestory_N26dianying_90060201_65_dialog_content = "With this poison, I can finally assassinate the city lord and bring peace to the world once again!",
  str_homestory_N26dianying_90060201_66_dialog_content = "P-Poison?!",
  str_homestory_N26dianying_90060201_67_dialog_content = "Since you already know who I am, I suppose there's no point in keeping it a secret.",
  str_homestory_N26dianying_90060201_68_dialog_content = "Your guess was correct: I am the world-class assassin you were searching for all along.",
  str_homestory_N26dianying_90060201_69_dialog_content = "W-Wait... I was looking for a killer this whole time?!",
  str_homestory_N26dianying_90060201_70_dialog_content = "My efforts to assassinate the island's ruler have been fruitless so far, but with this poison...",
  str_homestory_N26dianying_90060201_71_dialog_content = "My efforts to assassinate the city lord have been fruitless so far, but with this poison...",
  str_homestory_N26dianying_90060201_72_dialog_content = "Hurry up and give it to me!",
  str_homestory_N26dianying_90060201_73_dialog_content = "No, no, no! I-I believe this must be some sort of misunderstanding!",
  str_homestory_N26dianying_90060201_74_dialog_content = "This elixir isn't poison at all! Besides...",
  str_homestory_N26dianying_90060201_75_dialog_content = "Aren't we in a landlocked country? What \"island ruler\" are you talking about?!",
  str_homestory_N26dianying_90060201_76_dialog_content = "Now that you mention it, it is a bit strange... I don't see the ocean anywhere around here!",
  str_homestory_N26dianying_90060201_77_dialog_content = "Of course not! We're thousands of miles from the nearest beach!",
  str_homestory_N26dianying_90060201_78_dialog_content = "The cherry blossom trees are different, as well... There are even fruits growing on them.",
  str_homestory_N26dianying_90060201_79_dialog_content = "What \"cherry blossom trees\"?! Those are peach trees!",
  str_homestory_N26dianying_90060201_80_dialog_content = "Aren't we in the open country? What \"city ruler\" are you talking about?!",
  str_homestory_N26dianying_90060201_81_dialog_content = "Where the heck did you even come from?!",
  str_homestory_N26dianying_90060201_82_dialog_content = "I'm not sure, either... All I know, is that I must carry out my assassination of the island's ruler.",
  str_homestory_N26dianying_90060201_83_dialog_content = "I'm not sure, either... All I know, is that I must carry out my assassination of the city lord.",
  str_homestory_N26dianying_90060201_84_dialog_content = "Then you should at least try to be in the right place!!",
  str_homestory_N26dianying_90060201_85_dialog_content = "You know what? Let's just pretend this conversation never happened... Sorry to disturb you.",
  str_homestory_N26dianying_90060201_86_dialog_content = "Also, try going east next time... You might even see the ocean someday.",
  str_homestory_N26dianying_90060201_87_dialog_content = "Also, try going east next time... You might even find the city you're looking for.",
  str_homestory_N26dianying_90060201_88_dialog_content = "But wait, the poison...",
  str_homestory_N26dianying_90060201_89_dialog_content = "Just forget about it! Good luck with your mission, and good day!!",
  str_homestory_N26dianying_90060201_90_dialog_content = "Ugh... Where the heck is this person I'm supposed to meet?",
  str_homestory_N26dianying_90060201_91_dialog_content = "I screwed up with that person just now... She was mysterious enough, but there was nothing heroic about her at all. Guess I'll just have to try again...",
  str_homestory_N26dianying_90060201_92_dialog_content = "Hey... That person looks pretty heroic to me!",
  str_homestory_N26dianying_90060201_93_dialog_content = "Innkeeper! Another pot of osmanthus wine!",
  str_homestory_N26dianying_90060201_94_dialog_content = "Coming right up! I'll just leave this here for you.",
  str_homestory_N26dianying_90060201_95_dialog_content = "There's no mistaking it... This has to be the right person!",
  str_homestory_N26dianying_90060201_96_dialog_content = "Pardon me, but would you care to have a drink with me?",
  str_homestory_N26dianying_90060201_97_dialog_content = "Oh? By all means.",
  str_homestory_N26dianying_90060201_98_dialog_content = "Oh? By all means.",
  str_homestory_N26dianying_90060201_99_dialog_content = "I ordered a pot of osmanthus wine! The innkeeper says that its flavor is quite unique. Is this... Something you would like?",
  str_homestory_N26dianying_90060201_100_dialog_content = "Yes.",
  str_homestory_N26dianying_90060201_101_dialog_content = "Like it? I love it!",
  str_homestory_N26dianying_90060201_102_dialog_content = "What the—?! You drank it all in one gulp!!",
  str_homestory_N26dianying_90060201_103_dialog_content = "For someone to like osmanthus wine this much... She must be the person I'm looking for!",
  str_homestory_N26dianying_90060201_104_dialog_content = "For someone to like osmanthus wine this much... He must be the person I'm looking for!",
  str_homestory_N26dianying_90060201_105_dialog_content = "Listen, hero, I know who you really are. You see, I...",
  str_homestory_N26dianying_90060201_106_dialog_content = "Shhh! Not so loud!",
  str_homestory_N26dianying_90060201_107_dialog_content = "Oh, right! I almost forgot... \"Utmost secrecy,\" and all that!",
  str_homestory_N26dianying_90060201_108_dialog_content = "You've come to make contact with me, yes? I've been waiting for so long...",
  str_homestory_N26dianying_90060201_109_dialog_content = "Hahahaha! So you finally decided to show up!",
  str_homestory_N26dianying_90060201_110_dialog_content = "You've come to make contact with me, yes?",
  str_homestory_N26dianying_90060201_111_dialog_content = "Th-That's right! Sorry for being so late!",
  str_homestory_N26dianying_90060201_112_dialog_content = "Think nothing of it. So long as you wish to become part of my crew, I can overlook it for once.",
  str_homestory_N26dianying_90060201_113_dialog_content = "Oh, don't you worry about that!",
  str_homestory_N26dianying_90060201_114_dialog_content = "Now then... Welcome aboard, my newest crew member!",
  str_homestory_N26dianying_90060201_115_dialog_content = "C-Crew?!",
  str_homestory_N26dianying_90060201_116_dialog_content = "Indeed. And since you were the first to arrive, you have the privilege of being my first mate.",
  str_homestory_N26dianying_90060201_117_dialog_content = "From now on, you can refer to me as \"skipper.\"",
  str_homestory_N26dianying_90060201_118_dialog_content = "Indeed. And since you were the first to arrive, you have the privilege of being my first mate.",
  str_homestory_N26dianying_90060201_119_dialog_content = "From now on, you can refer to me as \"skipper.\"",
  str_homestory_N26dianying_90060201_120_dialog_content = "Wait, wait, wait... I think there's been some sort of misunderstanding again...",
  str_homestory_N26dianying_90060201_121_dialog_content = "What kind of skipper are you, exactly? We're completely landlocked here, and there isn't a ship to be seen for thousands of miles!",
  str_homestory_N26dianying_90060201_122_dialog_content = "You realize it too, then? This place is suffering from a severe lack of seafaring vessels...",
  str_homestory_N26dianying_90060201_123_dialog_content = "But if I manage to craft a ship here, I'll be the very first skipper in the entire town! A prestigious honor, wouldn't you agree?",
  str_homestory_N26dianying_90060201_124_dialog_content = "You realize it too, then? This place is suffering from a severe lack of seafaring vessels...",
  str_homestory_N26dianying_90060201_125_dialog_content = "But if I manage to craft a ship here, I'll be the very first skipper in the entire town! A prestigious honor, wouldn't you agree?",
  str_homestory_N26dianying_90060201_126_dialog_content = "Well, as much as I admire your pioneering spirit...",
  str_homestory_N26dianying_90060201_127_dialog_content = "Don't you think the lack of ships has something to do with, I dunno... the lack of a body of water?!",
  str_homestory_N26dianying_90060201_128_dialog_content = "Heh... A ship doesn't NEED water in order to sail.",
  str_homestory_N26dianying_90060201_129_dialog_content = "Heh... A ship doesn't NEED water in order to sail.",
  str_homestory_N26dianying_90060201_130_dialog_content = "What the heck is that supposed to mean?!",
  str_homestory_N26dianying_90060201_131_dialog_content = "Rest assured, I have taken all of these questions into consideration.",
  str_homestory_N26dianying_90060201_132_dialog_content = "Rest assured, I have taken all of these questions into consideration.",
  str_homestory_N26dianying_90060201_133_dialog_content = "Really? Because I beg to differ!",
  str_homestory_N26dianying_90060201_134_dialog_content = "Once enough people join our crew, we can ask the kingdom for their support! Everything will work out once we reach that point!",
  str_homestory_N26dianying_90060201_135_dialog_content = "Once enough people join our crew, we can ask the kingdom for their support! Everything will work out once we reach that point!",
  str_homestory_N26dianying_90060201_136_dialog_content = "... You know what? I just remembered I get seasick very easily! Also, I have some other business to attend to!",
  str_homestory_N26dianying_90060201_137_dialog_content = "I'll be going now!",
  str_homestory_N26dianying_90060201_138_dialog_content = "But wait, what about being my first mate?",
  str_homestory_N26dianying_90060201_139_dialog_content = "But wait, what about being my first mate?",
  str_homestory_N26dianying_90060201_140_dialog_content = "I'm really not cut out for the swashbuckling life, I promise! Best of luck!",
  str_homestory_N26dianying_90060201_141_dialog_content = "Jeez... Is there even a single normal person in this place?!",
  str_homestory_N26dianying_90060201_142_dialog_content = "Who else could it be...?",
  str_homestory_N26dianying_90060201_143_dialog_content = "Oh no... There's only one person I haven't asked yet.",
  str_homestory_N26dianying_90060201_144_dialog_content = "But they don't match the quest's description at all... What should I do?",
  str_homestory_N26dianying_90060201_145_dialog_content = "Ah, forget it... I'm already here, so I may as well give it a shot.",
  str_homestory_N26dianying_90060201_146_dialog_content = "Innkeeper! One more pot, please!",
  str_homestory_N26dianying_90060201_147_dialog_content = "Very well, but... You know this is your third pot, right?",
  str_homestory_N26dianying_90060201_148_dialog_content = "I had no idea you enjoyed osmanthus wine so much.",
  str_homestory_N26dianying_90060201_149_dialog_content = "T-To be honest, I haven't even had a sip of the stuff...",
  str_homestory_N26dianying_90060201_150_dialog_content = "Please let this weird-looking customer be the person I'm looking for...",
  str_homestory_N26dianying_90060201_151_dialog_content = "Pardon me, but would you like to—",
  str_homestory_N26dianying_90060201_152_dialog_content = "You're finally here!",
  str_homestory_N26dianying_90060201_153_dialog_content = "Huh?!",
  str_homestory_N26dianying_90060201_154_dialog_content = "S-Sorry, your response kind of caught me off-guard...",
  str_homestory_N26dianying_90060201_155_dialog_content = "You know who I am, right?",
  str_homestory_N26dianying_90060201_156_dialog_content = "I-I do? Sorry, but I can't be sure of anything anymore...",
  str_homestory_N26dianying_90060201_157_dialog_content = "The last two people I approached were... something else.",
  str_homestory_N26dianying_90060201_158_dialog_content = "I come from a thousand years in the future!",
  str_homestory_N26dianying_90060201_159_dialog_content = "And you're no different!!!",
  str_homestory_N26dianying_90060201_160_dialog_content = "I was stranded at this point after an input error caused my teleporter to malfunction critically.",
  str_homestory_N26dianying_90060201_161_dialog_content = "But you're here to take me back, right?",
  str_homestory_N26dianying_90060201_162_dialog_content = "... I didn't understand a single word that came out of your mouth just now.",
  str_homestory_N26dianying_90060201_163_dialog_content = "Wait, so you're NOT going to take me back to my time? Lame.",
  str_homestory_N26dianying_90060201_164_dialog_content = "Aaargh! I've completely failed in my quest!",
  str_homestory_N26dianying_90060201_165_dialog_content = "Quest?",
  str_homestory_N26dianying_90060201_166_dialog_content = "Quest? What quest?",
  str_homestory_N26dianying_90060201_167_dialog_content = "Oh, forget it... It doesn't matter anymore.",
  str_homestory_N26dianying_90060201_168_dialog_content = "Sorry, but I'm not the person you're looking for.",
  str_homestory_N26dianying_90060201_169_dialog_content = "Still, I have to ask... What's someone from the future doing in a place like this?",
  str_homestory_N26dianying_90060201_170_dialog_content = "A thousand years in the future, my laboratory is located in this very location.",
  str_homestory_N26dianying_90060201_171_dialog_content = "That's because my lab is sitting in this exact spot! Just a thousand years in the future, of course.",
  str_homestory_N26dianying_90060201_172_dialog_content = "Anyways, my fellow researchers should be here to rescue me soon enough... Any minute now.",
  str_homestory_N26dianying_90060201_173_dialog_content = "So that's why you've been waiting here all along? Isn't there another way to return to your time?",
  str_homestory_N26dianying_90060201_174_dialog_content = "Well, I could just wait another thousand years?",
  str_homestory_N26dianying_90060201_175_dialog_content = "Not really. I can't contact my colleagues at all from this point in time.",
  str_homestory_N26dianying_90060201_176_dialog_content = "If I can't reach them, then I'll just have to wait until the laboratory is built again.",
  str_homestory_N26dianying_90060201_177_dialog_content = "You're just gonna sit here for a millennium?!",
  str_homestory_N26dianying_90060201_178_dialog_content = "If that's what it takes, then yes.",
  str_homestory_N26dianying_90060201_179_dialog_content = "That's, uh... Going to require a lot of patience.",
  str_homestory_N26dianying_90060201_180_dialog_content = "Sigh... If only my hero had that kind of patience!",
  str_homestory_N26dianying_90060201_181_dialog_content = "Still, I don't blame them for not being here. If anything, it's my fault for being so late...",
  str_homestory_N26dianying_90060201_182_dialog_content = "You could always spend the next thousand years keeping me company?",
  str_homestory_N26dianying_90060201_183_dialog_content = "Gee, thanks for the kind offer...",
  str_homestory_N26dianying_90060201_184_dialog_content = "I just wish I could be as optimistic about things as you...",
  str_homestory_N26dianying_90060201_185_dialog_content = "Hey! Listen up, you complacent pigs!",
  str_homestory_N26dianying_90060201_186_dialog_content = "Huh? What's with all the yelling outside?",
  str_homestory_N26dianying_90060201_187_dialog_content = "This mountain belongs to me, you hear?",
  str_homestory_N26dianying_90060201_188_dialog_content = "If you've got any brains between your ears, leave your valuables behind and get lost! If you don't, I'll smash what little brains you DO have on the ground!",
  str_homestory_N26dianying_90060201_189_dialog_content = "Bandits?! Oh, this is bad!",
  str_homestory_N26dianying_90060201_190_dialog_content = "I'm no match for all of them at once! I gotta find a way out of here...",
  str_homestory_N26dianying_90060201_191_dialog_content = "Damn... If I fight them, my cover will be blown. Time to retreat...",
  str_homestory_N26dianying_90060201_192_dialog_content = "That was fast!!",
  str_homestory_N26dianying_90060201_193_dialog_content = "Oh, great! Just look at all those eager faces! They must have come to join my crew!",
  str_homestory_N26dianying_90060201_194_dialog_content = "I should go greet them!",
  str_homestory_N26dianying_90060201_195_dialog_content = "Oh, great! Just look at all those eager faces! They must have come to join my crew!",
  str_homestory_N26dianying_90060201_196_dialog_content = "I should go greet them!",
  str_homestory_N26dianying_90060201_197_dialog_content = "G-Get back in here! Don't you have even the slightest grip on reality?!",
  str_homestory_N26dianying_90060201_198_dialog_content = "This won't do... I can't let a horde of bandits take over the laboratory's future site.",
  str_homestory_N26dianying_90060201_199_dialog_content = "I'll go exterminate them.",
  str_homestory_N26dianying_90060201_200_dialog_content = "By yourself? But it sounds like there's a bunch of them out there!",
  str_homestory_N26dianying_90060201_201_dialog_content = "Wow... Just like that, the only ones left here are the innkeeper and myself...",
  str_homestory_N26dianying_90060201_202_dialog_content = "This just isn't my day... First I fail to make contact with the right person, then we get attacked by bandits...",
  str_homestory_N26dianying_90060201_203_dialog_content = "Do I still need to pay my tab if we all end up dead?",
  str_homestory_N26dianying_90060201_204_dialog_content = "So you've given up on your search, have you?",
  str_homestory_N26dianying_90060201_205_dialog_content = "Yeah... I suppose it's time to accept my fate...",
  str_homestory_N26dianying_90060201_206_dialog_content = "W-Wait, how'd you know about that?!",
  str_homestory_N26dianying_90060201_207_dialog_content = "My quest is supposed to be top-secret!",
  str_homestory_N26dianying_90060201_208_dialog_content = "The person you were looking for was here all along...",
  str_homestory_N26dianying_90060201_209_dialog_content = "But that didn't necessarily make them a customer.",
  str_homestory_N26dianying_90060201_210_dialog_content = "Wait, you don't mean...",
  str_homestory_N26dianying_90060201_211_dialog_content = "Could it be...?!",
  str_homestory_N26dianying_90060201_212_dialog_content = "Are YOU the warrior I'm supposed to meet?!",
  str_homestory_N26dianying_90060201_213_dialog_content = "No way! This can't be!",
  str_homestory_N26dianying_90060201_214_dialog_content = "The person in the quest is supposed to be \"in the prime of their life\"! Their martial arts are supposed to be second to none! But you...",
  str_homestory_N26dianying_90060201_215_dialog_content = "Your face is so worn... And you're confined to a wheelchair! How could you be the person I'm looking for?!",
  str_homestory_N26dianying_90060201_216_dialog_content = "Heh, quite the fanciful description... But it fits, all the same. The warrior you came here to find is none other than yours truly.",
  str_homestory_N26dianying_90060201_217_dialog_content = "Only... You came too late.",
  str_homestory_N26dianying_90060201_218_dialog_content = "Ten years too late, in fact!",
  str_homestory_N26dianying_90060201_219_dialog_content = "Ten years?!",
  str_homestory_N26dianying_90060201_220_dialog_content = "What?!?",
  str_homestory_N26dianying_90060201_221_dialog_content = "My legs were seriously wounded ten years ago, so I went into hiding here. I've been waiting for a hero to bring me a healing elixir.",
  str_homestory_N26dianying_90060201_222_dialog_content = "But no matter how long I waited... That hero never came.",
  str_homestory_N26dianying_90060201_223_dialog_content = "Much has changed in the last ten years. I forced myself to drink osmanthus wine every day, and eventually, I developed a taste for it.",
  str_homestory_N26dianying_90060201_224_dialog_content = "Because the elixir never came, my legs gradually worsened, and I ended up in a wheelchair.",
  str_homestory_N26dianying_90060201_225_dialog_content = "I became close friends with the previous owner of this inn, and when he eventually passed away... I was surprised to learn that he had entrusted it to me.",
  str_homestory_N26dianying_90060201_226_dialog_content = "I never expected that, after all this time, you would still appear.",
  str_homestory_N26dianying_90060201_227_dialog_content = "Oh, uh...",
  str_homestory_N26dianying_90060201_228_option_content = "Apologize sincerely",
  str_homestory_N26dianying_90060201_229_dialog_content = "Don't just stand there! Apologize, right now!",
  str_homestory_N26dianying_90060201_230_dialog_content = "F-Forgive me, brave hero! From the bottom of my heart, I'm so terribly sorry!",
  str_homestory_N26dianying_90060201_231_dialog_content = "I-If only I wasn't so tardy...",
  str_homestory_N26dianying_90060201_232_dialog_content = "You were ten years \"tardy\"? Don't you think that's a bit of an understatement?",
  str_homestory_N26dianying_90060201_233_dialog_content = "It's all my fault... I misplaced the quest scroll somewhere in my house...",
  str_homestory_N26dianying_90060201_234_dialog_content = "It wasn't until I started packing to move out that I finally found it. The only problem was that I forgot how old the request actually was...",
  str_homestory_N26dianying_90060201_235_dialog_content = "It's fine. Had this happened a few years ago, I might have been upset, but now... I can't help but find it amusing. Laughable, even.",
  str_homestory_N26dianying_90060201_236_dialog_content = "You appear to be completely sincere, so I won't pursue the matter. My adventuring days are far behind me; I only wish to spend the rest of my life in peace.",
  str_homestory_N26dianying_90060201_237_dialog_content = "Still, I left quite a few matters unfinished in the past... If you truly wish to make amends, you could take care of them in my stead?",
  str_homestory_N26dianying_90060201_238_dialog_content = "Really? Of course, I'd be more than willing to help!",
  str_homestory_N26dianying_90060201_239_dialog_content = "An old partner of mine from my adventuring days lives nearby. Just like myself, he has chosen to keep his identity hidden, and works over in the market.",
  str_homestory_N26dianying_90060201_240_dialog_content = "I have a letter for him, and I want you to fulfill my mission by delivering it to him.",
  str_homestory_N26dianying_90060201_241_dialog_content = "Understood! I just have to meet with another anonymous contact, right? I definitely have experience with this kind of quest now!",
  str_homestory_N26dianying_90060201_242_dialog_content = "I certainly hope so.",
  str_homestory_N26dianying_90060201_243_dialog_content = "There is no room for any more of your \"tardiness\" when it comes to delivering this letter.",
  str_homestory_N26dianying_90060201_244_dialog_content = "The person in question is even older than I am. I doubt he'll live to see another decade go by.",
  str_homestory_N26dianying_90060201_245_option_content = "Make up an excuse",
  str_homestory_N26dianying_90060201_246_dialog_content = "Did you forget? Think about the reason you were so late!",
  str_homestory_N26dianying_90060201_247_dialog_content = "Oh, right! It's because I had too many quests on my hands!",
  str_homestory_N26dianying_90060201_248_dialog_content = "You see, with the land in such a state of disarray, I had so many heroes reaching out to me that I couldn't keep track of them all!",
  str_homestory_N26dianying_90060201_249_dialog_content = "Some of them were already on death's doorstep, so I had to prioritize them.",
  str_homestory_N26dianying_90060201_250_dialog_content = "U-Unfortunately... That's why it took so long for me to come to find you.",
  str_homestory_N26dianying_90060201_251_dialog_content = "Is that so? I had no idea there were so many heroes in distress...",
  str_homestory_N26dianying_90060201_252_dialog_content = "Why don't you name a few of them for me? Who knows, maybe I knew them back in my day?",
  str_homestory_N26dianying_90060201_253_dialog_content = "I would feel much better knowing that my old comrades were taken care of, even if it came at my own expense.",
  str_homestory_N26dianying_90060201_254_dialog_content = "S-Sure, just a moment...",
  str_homestory_N26dianying_90060201_255_dialog_content = "Take all the time you need. After all, I waited ten years for you... I could wait for ten more.",
  str_homestory_N26dianying_90060201_256_dialog_content = "If you can't recall their names, then maybe I could introduce you to some of them? That might jog your memory...",
  str_homestory_N26dianying_90060201_257_dialog_content = "I-Introduce me to them?",
  str_homestory_N26dianying_90060201_258_dialog_content = "That's right, although I shouldn't call them \"heroes\" anymore. You see, some of them started going down the wrong path in the past...",
  str_homestory_N26dianying_90060201_259_dialog_content = "In fact, I believe a few of them are standing right outside my door, waiting for a chance to talk about the good old days.",
  str_homestory_N26dianying_90060201_260_dialog_content = "You don't mean the bandits... Do you?!",
  str_homestory_N26dianying_90060201_261_dialog_content = "No, please! I don't want to meet them!",
  str_homestory_N26dianying_90060201_262_dialog_content = "I was wrong, Mr. Innkeeper! I'm sorry!!!",
  str_homestory_N26dianying_90060201_263_option_content = "Complete the quest",
  str_homestory_N26dianying_90060201_264_dialog_content = "Don't forget! You still have a quest to complete!",
  str_homestory_N26dianying_90060201_265_dialog_content = "None of that matters now! I've brought you the elixir you requested, brave hero!",
  str_homestory_N26dianying_90060201_266_dialog_content = "And while I was a bit late with the delivery... My quest is finally complete!",
  str_homestory_N26dianying_90060201_267_dialog_content = "\"A bit late,\" you say?",
  str_homestory_N26dianying_90060201_268_dialog_content = "I had no idea a decade was such a trifling amount of time...",
  str_homestory_N26dianying_90060201_269_dialog_content = "I-I'm really sorry about that... It's just that I misplaced the quest scroll somewhere in my house...",
  str_homestory_N26dianying_90060201_270_dialog_content = "It wasn't until I started packing to move out that I finally found it. The only problem was that I forgot how old the request actually was...",
  str_homestory_N26dianying_90060201_271_dialog_content = "In any case, I brought it all this way, so here you go. Who knows, it might just fix your legs right up!",
  str_homestory_N26dianying_90060201_272_dialog_content = "This way, I can turn in my quest when I get back.",
  str_homestory_N26dianying_90060201_273_dialog_content = "I've got no need for it anymore. My legs are done for, and no amount of elixir could possibly mend them.",
  str_homestory_N26dianying_90060201_274_dialog_content = "Just keep it for yourself. You might end up needing it someday.",
  str_homestory_N26dianying_90060201_275_dialog_content = "I don't know about that... Besides, I can't turn in my quest if you don't take it.",
  str_homestory_N26dianying_90060201_276_dialog_content = "Well, we do happen to be surrounded by a group of bloodthirsty bandits...",
  str_homestory_N26dianying_90060201_277_dialog_content = "I think you might need it more than you think very soon.",
  str_homestory_N26dianying_90060201_278_dialog_content = "What?!?",
  str_homestory_N26dianying_90060201_279_dialog_content = "No, please! Save me, great and merciful hero!",
  str_homestory_N26dianying_90060201_280_dialog_content = "Innkeeper! A pot of your finest osmanthus wine, please!",
  str_homestory_N26dianying_90060201_281_dialog_content = "Sorry, but we're all out.",
  str_homestory_N26dianying_90060201_282_dialog_content = "What? \"All out\"?!",
  str_homestory_N26dianying_90060201_283_dialog_content = "That's right. I don't have a drop of the stuff on hand at the moment.",
  str_homestory_N26dianying_90060201_284_dialog_content = "How could you run out at a time like this? Everything's ruined now!",
  str_homestory_N26dianying_90060201_285_dialog_content = "I could always send for some, if you'd like?",
  str_homestory_N26dianying_90060201_286_dialog_content = "If you're so intent on having this kind of wine today, I can order some from a neighboring shop. It will take some time, but it can be done.",
  str_homestory_N26dianying_90060201_287_dialog_content = "R-Really?",
  str_homestory_N26dianying_90060201_288_dialog_content = "Fine, I can wait!",
  str_homestory_N26dianying_90060201_289_dialog_content = "This osmanthus wine has a very unique taste. Not many folks drink this nowadays, but please enjoy.",
  str_homestory_N26dianying_90060201_290_dialog_content = "Still, it does my heart good to see someone else who appreciates my favorite drink.",
  str_homestory_N26dianying_90060201_291_dialog_content = "Just set it off to the side when it gets here, please. Everything will be ruined if I don't have a pot of it...",
  str_homestory_N26dianying_90060201_292_dialog_content = "<color=#e8d9bb>Knock, knock, knock!</color>",
  str_homestory_N26dianying_90060201_293_dialog_content = "Someone's at the door! Did they bring the osmanthus wine?",
  str_homestory_N26dianying_90060201_294_dialog_content = "Shhh! That voice...",
  str_homestory_N26dianying_90060201_295_dialog_content = "Hey! Listen up, you complacent pigs!",
  str_homestory_N26dianying_90060201_296_dialog_content = "This mountain belongs to me, you hear?",
  str_homestory_N26dianying_90060201_297_dialog_content = "If you've got any brains between your ears, leave your valuables behind and get lost! If you don't, I'll smash what little brains you DO have on the ground!",
  str_homestory_N26dianying_90060201_298_dialog_content = "Bandits? Now, of all times?!",
  str_homestory_N26dianying_90060201_299_dialog_content = "Damn... If I fight them, my cover will be blown. Time to retreat...",
  str_homestory_N26dianying_90060201_300_dialog_content = "Oh, great! I'll go greet them!",
  str_homestory_N26dianying_90060201_301_dialog_content = "Oh, great! I'll go greet them!",
  str_homestory_N26dianying_90060201_302_dialog_content = "Exterminate them all.",
  str_homestory_N26dianying_90060201_303_dialog_content = "Unfortunately, it appears my humble inn is about to be ransacked by a gang of bandits.",
  str_homestory_N26dianying_90060201_304_dialog_content = "Now then, if you would be so kind as to escape from the back...",
  str_homestory_N26dianying_90060201_305_dialog_content = "Well, I'd love to escape with my life and all...",
  str_homestory_N26dianying_90060201_306_dialog_content = "But what about my quest?!",
  str_homestory_N26dianying_90060301_1_dialog_content = "The flames of war have ravaged our world for many years now... With each passing day, our struggle against the Eclipsites seems more and more hopeless.",
  str_homestory_N26dianying_90060301_2_dialog_content = "Only the long-lost Heavenly Blade, a sacred and powerful weapon, can put an end to the strife and bring peace to the world once more.",
  str_homestory_N26dianying_90060301_3_dialog_content = "... Or so the legend says. Isn't that right, my faithful servant?",
  str_homestory_N26dianying_90060301_4_dialog_content = "<size=45>Yes, my lord!</size>",
  str_homestory_N26dianying_90060301_5_dialog_content = "Argh, my ears! Keep your voice down, fool!",
  str_homestory_N26dianying_90060301_6_dialog_content = "Ahem... As the envoy of the Dragonscorch, the most powerful force in the land, I have my reasons for summoning you here today.",
  str_homestory_N26dianying_90060301_7_dialog_content = "Despite only recently joining our faction, you have already proven yourself to be a loyal and capable servant.",
  str_homestory_N26dianying_90060301_8_dialog_content = "Now then, the legend also says that the Heavenly Blade was last seen in the Village of Dragons. From what I understand, you are also from the very same village, are you not?",
  str_homestory_N26dianying_90060301_9_dialog_content = "<size=45>Yes, my lord!</size>",
  str_homestory_N26dianying_90060301_10_dialog_content = "Excellent... Then I hereby entrust you with a sacred duty: return to the Village of Dragons, and find the Heavenly Blade in my place.",
  str_homestory_N26dianying_90060301_11_dialog_content = "Rest assured, my lord, I will not fail you!",
  str_homestory_N26dianying_90060301_12_dialog_content = "It is now 11:15 in the morning... Starting right now, you have exactly three days to find the blade and bring it to me.",
  str_homestory_N26dianying_90060301_13_dialog_content = "(Wait... Did he say \"11:15\"?!)",
  str_homestory_N26dianying_90060301_14_dialog_content = "Er, my lord? I, uh... I just realized that I still need to pack some supplies before I depart on my noble quest!",
  str_homestory_N26dianying_90060301_15_dialog_content = "Very well, then. See to your supplies and be on your way, but make it quick!",
  str_homestory_N26dianying_90060301_16_dialog_content = "Gasp, gasp, gasp...",
  str_homestory_N26dianying_90060301_17_dialog_content = "M-Master! My apologies for the slight delay!",
  str_homestory_N26dianying_90060301_18_dialog_content = "\"Slight,\" you say? You are thirty minutes late.",
  str_homestory_N26dianying_90060301_19_dialog_content = "Sigh... It matters not. I have summoned you today because I require your assistance with a matter of the utmost importance.",
  str_homestory_N26dianying_90060301_20_dialog_content = "Surely, you have heard the legend of the Heavenly Blade? \"The flames of war have ravaged our world for many years now...\"",
  str_homestory_N26dianying_90060301_21_dialog_content = "My lord, could it be that... You also wish for me to go to the Village of Dragons in search of the Heavenly Blade?",
  str_homestory_N26dianying_90060301_22_dialog_content = "That is correct. By finding the Heavenly Blade, the Zakura Faction will bring order to this chaotic world, and solidify its place as the most powerful force in existence.",
  str_homestory_N26dianying_90060301_23_dialog_content = "Wait... What do you mean, \"also\"?",
  str_homestory_N26dianying_90060301_24_dialog_content = "Oh! N-Nothing, my lord!",
  str_homestory_N26dianying_90060301_25_dialog_content = "(If the envoys from both factions find out that I'm carrying out the same mission for them...)",
  str_homestory_N26dianying_90060301_26_dialog_content = "(I'll be as good as dead!)",
  str_homestory_N26dianying_90060301_27_dialog_content = "While you are still lacking in experience, my sources tell me that the blade can be found somewhere in your hometown, the Village of Dragons. You are the only person I can trust with this quest.",
  str_homestory_N26dianying_90060301_28_dialog_content = "<size=45>Yes, my lord!</size>",
  str_homestory_N26dianying_90060301_29_dialog_content = "H-However, I still have a few things to discuss with my comrades before I depart...",
  str_homestory_N26dianying_90060301_30_dialog_content = "Very well, but try to keep it brief. Oh, and remember to check the weather for me before you leave.",
  str_homestory_N26dianying_90060301_31_dialog_content = "Gasp, gasp, gasp...",
  str_homestory_N26dianying_90060301_32_dialog_content = "M-My lord! The weather today is fair, a perfect day for training your soldiers!",
  str_homestory_N26dianying_90060301_33_dialog_content = "Hmm? I don't recall asking you for a weather report?",
  str_homestory_N26dianying_90060301_34_dialog_content = "(Oh, crap! Wrong lord!)",
  str_homestory_N26dianying_90060301_35_dialog_content = "If you are finished with your preparations, then depart immediately! Should you succeed, your rewards shall be plentiful!",
  str_homestory_N26dianying_90060301_36_dialog_content = "Oh, and if you happen to see the sunflowers blooming during your journey, find a way to send word to me. Understood?",
  str_homestory_N26dianying_90060301_37_dialog_content = "Yes, my lord! I'll leave right away!",
  str_homestory_N26dianying_90060301_38_dialog_content = "Gasp, gasp, gasp...",
  str_homestory_N26dianying_90060301_39_dialog_content = "I'm back, my lord! The sunflowers are blooming and full of seeds! They can be harvested at any time for the soldiers' rations!",
  str_homestory_N26dianying_90060301_40_dialog_content = "Hmm? And when exactly did I ask for a report on the sunflowers?",
  str_homestory_N26dianying_90060301_41_dialog_content = "Oh, and during your journey, if you notice that the reeds have grown tall, find a way to send word to me. Understood?",
  str_homestory_N26dianying_90060301_42_dialog_content = "Yes, my lord! I'll leave right away!",
  str_homestory_N26dianying_90060301_43_dialog_content = "Gasp, gasp, gasp...",
  str_homestory_N26dianying_90060301_44_dialog_content = "I'm back, my lord! The reeds are both tall and dense now, perfect for concealing a surprise attack on your enemies!",
  str_homestory_N26dianying_90060301_45_dialog_content = "Oh? And when exactly did I ask for a report on the reeds?",
  str_homestory_N26dianying_90060301_46_dialog_content = "Oh, and during your journey, if you notice that the wheat fields have reached full maturity, find a way to send word to me. Understood?",
  str_homestory_N26dianying_90060301_47_dialog_content = "Yes, my lord! I'll leave right away!",
  str_homestory_N26dianying_90060301_48_dialog_content = "Gasp, gasp, gasp...",
  str_homestory_N26dianying_90060301_49_dialog_content = "I'm back, my lord! The wheat fields are full and ready for harvesting! The soldiers will eat well this winter!",
  str_homestory_N26dianying_90060301_50_dialog_content = "Oh? And when exactly did I ask for a report on the wheat fields?",
  str_homestory_N26dianying_90060301_50X1_dialog_content = "Oh, and during your journey, if you notice any suspicious people, find a way to send word to me. Understood?",
  str_homestory_N26dianying_90060301_50X2_dialog_content = "Yes, my lord! I'll leave right away!",
  str_homestory_N26dianying_90060301_50X3_dialog_content = "Gasp, gasp, gasp...",
  str_homestory_N26dianying_90060301_50X4_dialog_content = "I'm back, my lord! There are no suspicious people nearby. We can start preparing for the training!",
  str_homestory_N26dianying_90060301_50X5_dialog_content = "Hmm? I don't recall asking you to report the nearby situation to me!",
  str_homestory_N26dianying_90060301_51_dialog_content = "(Crap! Not again!!)",
  str_homestory_N26dianying_90060301_52_dialog_content = "If you are finished saying farewell to your friends, then make haste to the Village of Dragons. You'll have my eternal gratitude should you succeed in your quest.",
  str_homestory_N26dianying_90060301_53_dialog_content = "Yes, my lord! I'll leave right away!",
  str_homestory_N26dianying_90060301_54_dialog_content = "(My lords, you are both wise and powerful men... So please forgive me!)",
  str_homestory_N26dianying_90060301_55_dialog_content = "(Two rewards for the price of one quest... It's just too good to pass up!)",
  str_homestory_N26dianying_90060301_56_dialog_content = "Whew... I finally made it to the Village of Dragons. This really takes me back...",
  str_homestory_N26dianying_90060301_57_dialog_content = "Step right up and take a look! Wonderous weapons from all over the world! Sacred swords and blades galore, all at drop-dead discounts!",
  str_homestory_N26dianying_90060301_58_dialog_content = "Come one, come all! I've got all kinds of sacred swords on sale here, but my Holy Water Shells are the real stars of the show!",
  str_homestory_N26dianying_90060301_59_dialog_content = "What? Sorry, did you say you have sacred swords for sale?",
  str_homestory_N26dianying_90060301_60_dialog_content = "If that's what you're looking for, then you've come to the right place! Heck, I even have the Heavenly Blade in stock, if you're interested?",
  str_homestory_N26dianying_90060301_61_dialog_content = "See that sword on the weapon rack over there? I'd be willing to part with it for the low, low price of 99,999,999 Nightium!",
  str_homestory_N26dianying_90060301_62_dialog_content = "If that's what you're looking for, then you've come to the right place! Heck, I even have the Heavenly Blade in stock, if you're interested?",
  str_homestory_N26dianying_90060301_63_dialog_content = "See that sword on the weapon rack over there? I'd be willing to part with it for the low, low price of 99,999,999 Nightium!",
  str_homestory_N26dianying_90060301_64_dialog_content = "That's so expensive! Could it really be the Heavenly Blade from the legends...?",
  str_homestory_N26dianying_90060301_65_dialog_content = "Heheheh... Not bad, eh? You've got an eye for quality, miss!",
  str_homestory_N26dianying_90060301_66_dialog_content = "Pretty impressive, huh? You've got an eye for quality, miss!",
  str_homestory_N26dianying_90060301_67_dialog_content = "This isn't the Heavenly Blade.",
  str_homestory_N26dianying_90060301_68_dialog_content = "Huh? H-How'd you know?!",
  str_homestory_N26dianying_90060301_69_dialog_content = "Huh? H-How'd you know?!",
  str_homestory_N26dianying_90060301_70_dialog_content = "I can't say for sure how I know... Call it intuition, I guess?",
  str_homestory_N26dianying_90060301_71_dialog_content = "Ahem... Well, you're right! That sword isn't the Heavenly Blade at all, because the real one...",
  str_homestory_N26dianying_90060301_72_dialog_content = "Is the sword right next to it!",
  str_homestory_N26dianying_90060301_73_dialog_content = "Ahem... Well, you're right! That sword isn't the Heavenly Blade at all, because the real one...",
  str_homestory_N26dianying_90060301_74_dialog_content = "Is the sword right next to it!",
  str_homestory_N26dianying_90060301_75_dialog_content = "Really? Let me see! ...Uh, pardon me, but this one isn't the real deal, either!",
  str_homestory_N26dianying_90060301_76_dialog_content = "(Damn... There's no fooling her!)",
  str_homestory_N26dianying_90060301_77_dialog_content = "(Damn... There's no fooling her!)",
  str_homestory_N26dianying_90060301_78_dialog_content = "I'm sure you already know, but here in the Village of Dragons, we don't try to cheat our own folks. Now could you please tell me where I can find the real Heavenly Blade?",
  str_homestory_N26dianying_90060301_79_dialog_content = "Fine, you win... Here you go.",
  str_homestory_N26dianying_90060301_80_dialog_content = "Fine, you win... Here you go.",
  str_homestory_N26dianying_90060301_81_dialog_content = "A video tape?!",
  str_homestory_N26dianying_90060301_82_dialog_content = "Go put this tape in that projector over there, and hit \"play.\"",
  str_homestory_N26dianying_90060301_83_dialog_content = "The projector will show you the answers you seek!",
  str_homestory_N26dianying_90060301_84_dialog_content = "Go put this tape in that projector over there, and hit \"play.\"",
  str_homestory_N26dianying_90060301_85_dialog_content = "The projector will show you the answers you seek!",
  str_homestory_N26dianying_90060301_86_dialog_content = "Hmm... It should start playing when I push this button, right?",
  str_homestory_N26dianying_90060301_87_dialog_content = "... Huh? Why isn't the image on the tape moving? There's no sound, either...",
  str_homestory_N26dianying_90060301_88_dialog_content = "Wait, it's starting to move!!",
  str_homestory_N26dianying_90060301_89_dialog_content = "Fine, you win... Here you go.",
  str_homestory_N26dianying_90060301_90_dialog_content = "Fine, you win... Here you go.",
  str_homestory_N26dianying_90060301_91_dialog_content = "... A map?!",
  str_homestory_N26dianying_90060301_92_dialog_content = "Take this map, and follow it to the marked location.",
  str_homestory_N26dianying_90060301_93_dialog_content = "The map will show you the answers you seek!",
  str_homestory_N26dianying_90060301_94_dialog_content = "Take this map, and follow it to the marked location.",
  str_homestory_N26dianying_90060301_95_dialog_content = "The map will show you the answers you seek!",
  str_homestory_N26dianying_90060301_96_dialog_content = "Hmm... I'm pretty sure I went the right way, didn't I?",
  str_homestory_N26dianying_90060301_97_dialog_content = "Still, I can barely make heads or tails of this map... The writing on it is barely legible, too...",
  str_homestory_N26dianying_90060301_98_dialog_content = "Hmm... I need to take a closer look at this!",
  str_homestory_N26dianying_90060301_99_dialog_content = "Fine, you win... Look over there.",
  str_homestory_N26dianying_90060301_100_dialog_content = "Fine, you win... Look over there.",
  str_homestory_N26dianying_90060301_101_dialog_content = "A mailbox?!",
  str_homestory_N26dianying_90060301_102_dialog_content = "Go read what the previous owner wrote on it.",
  str_homestory_N26dianying_90060301_103_dialog_content = "The mailbox will show you the answers you seek!",
  str_homestory_N26dianying_90060301_104_dialog_content = "Go read what the previous owner wrote on it.",
  str_homestory_N26dianying_90060301_105_dialog_content = "The mailbox will show you the answers you seek!",
  str_homestory_N26dianying_90060301_106_dialog_content = "Hmm... This mailbox is pretty tall, huh?",
  str_homestory_N26dianying_90060301_107_dialog_content = "But even from down here, I can tell that the writing is almost too sloppy to read...",
  str_homestory_N26dianying_90060301_108_dialog_content = "Hmm... I need to take a closer look at this!",
  str_homestory_N26dianying_90060301_108X1_dialog_content = "Fine, you win... Here you go. Head towards the direction I'm facing.",
  str_homestory_N26dianying_90060301_108X2_dialog_content = "Fine, you win... Here you go. Head towards the direction I'm facing.",
  str_homestory_N26dianying_90060301_108X3_dialog_content = "Where am I going to?",
  str_homestory_N26dianying_90060301_108X4_dialog_content = "Um, don't worry about that. Just keep walking forward!",
  str_homestory_N26dianying_90060301_108X5_dialog_content = "There's always new hope ahead of you in the Village of Dragons, a land of outstanding people!",
  str_homestory_N26dianying_90060301_108X6_dialog_content = "Um, don't worry about that. Just keep walking forward!",
  str_homestory_N26dianying_90060301_108X7_dialog_content = "There's always new hope ahead of you in the Village of Dragons, a land of outstanding people!",
  str_homestory_N26dianying_90060301_108X8_dialog_content = "R-Really!? Isn't that too casual...",
  str_homestory_N26dianying_90060301_108X9_dialog_content = "Geez, I was right. I've been walking for so long... The boss must be a trickster!",
  str_homestory_N26dianying_90060301_108X10_dialog_content = "Huh? Could this be...",
  str_homestory_N26dianying_90060301_109_dialog_content = "\"The way of the world is to seek personal gain, and for this reason, the world will never change. In order to prevent the Heavenly Blade from falling into the hands of the wicked...\"",
  str_homestory_N26dianying_90060301_110_dialog_content = "\"An ancient well in the Village of Dragons was blessed with the power to reveal the legendary sword.\"",
  str_homestory_N26dianying_90060301_111_dialog_content = "\"Imbued with mysterious Luminatics, this well will not show the reflection of any object held up to its waters.\"",
  str_homestory_N26dianying_90060301_112_dialog_content = "\"When the true Heavenly Blade draws near, its divine image will appear within the well...\"",
  str_homestory_N26dianying_90060301_113_dialog_content = "\"The way of the world is to seek personal gain, and for this reason, the world will never change. In order to prevent the Heavenly Blade from falling into the hands of the wicked...\"",
  str_homestory_N26dianying_90060301_114_dialog_content = "\"A lounging chair in the Village of dragons was blessed with the power to reveal the legendary sword.\"",
  str_homestory_N26dianying_90060301_115_dialog_content = "\"Imbued with mysterious Luminatics, this chair will not allow any person to rest upon its seat.\"",
  str_homestory_N26dianying_90060301_116_dialog_content = "\"When the true Heavenly Blade draws near, its divine image will appear upon the seat...\"",
  str_homestory_N26dianying_90060301_117_dialog_content = "\"The way of the world is to seek personal gain, and for this reason, the world will never change. In order to prevent the Heavenly Blade from falling into the hands of the wicked...\"",
  str_homestory_N26dianying_90060301_118_dialog_content = "\"A piano in the Village of Dragons was blessed with the power to reveal the legendary sword.\"",
  str_homestory_N26dianying_90060301_119_dialog_content = "\"Imbued with mysterious Luminatics, this piano will not allow anyone to play it.\"",
  str_homestory_N26dianying_90060301_120_dialog_content = "\"When the true Heavenly Blade draws near, its divine image will appear upon the piano's keys...\"",
  str_homestory_N26dianying_90060301_121_dialog_content = "... Yao? Is that you, Yao?",
  str_homestory_N26dianying_90060301_122_dialog_content = "Yao? Is it really you?",
  str_homestory_N26dianying_90060301_123_dialog_content = "It's me, the girl next door from when we were kids! I haven't seen you in ages, Yao!",
  str_homestory_N26dianying_90060301_124_dialog_content = "Not since the day you left the village to find work... I thought I'd never see you again!",
  str_homestory_N26dianying_90060301_125_dialog_content = "Anyways, are you looking for something, by any chance?",
  str_homestory_N26dianying_90060301_126_dialog_content = "After we both left the village to find work... I thought I'd never see you again!",
  str_homestory_N26dianying_90060301_127_dialog_content = "Anyways, are you looking for something, by any chance?",
  str_homestory_N26dianying_90060301_128_dialog_content = "It's a long story, but... Do you still remember where to find that well? You know the one, right?",
  str_homestory_N26dianying_90060301_129_dialog_content = "It's a long story, but... Do you still remember where to find that lounging chair? You know the one, right?",
  str_homestory_N26dianying_90060301_130_dialog_content = "It's a long story, but... Do you still remember where to find that piano? You know the one, right?",
  str_homestory_N26dianying_90060301_131_dialog_content = "Sure, just follow me and I'll show you.",
  str_homestory_N26dianying_90060301_132_dialog_content = "Here we are!",
  str_homestory_N26dianying_90060301_133_dialog_content = "Sure, just follow me and I'll show you.",
  str_homestory_N26dianying_90060301_134_dialog_content = "Alright, here we are!",
  str_homestory_N26dianying_90060301_135_dialog_content = "So... Did you really come home just to see this well?",
  str_homestory_N26dianying_90060301_136_dialog_content = "So... Did you really come home just to see this chair?",
  str_homestory_N26dianying_90060301_137_dialog_content = "So... Did you really come home just to see this piano?",
  str_homestory_N26dianying_90060301_138_dialog_content = "Well, the truth is... I came to search for clues about the Heavenly Blade's whereabouts.",
  str_homestory_N26dianying_90060301_139_dialog_content = "My lords ordered me to find it, and bring it back to them as soon as possible.",
  str_homestory_N26dianying_90060301_140_dialog_content = "<color=#FFB400>\"Lords\"</color>? As in \"more than one\"?",
  str_homestory_N26dianying_90060301_141_dialog_content = "<color=#FFB400>\"Lords\"</color>? As in \"more than one\"? ...Oh, you mean your bosses!",
  str_homestory_N26dianying_90060301_142_dialog_content = "That's right... Both of them entrusted me with the same quest, at the same exact time, so I'm here.",
  str_homestory_N26dianying_90060301_143_dialog_content = "Although, I'm not sure what I'm going to do once I find it... How should I decide who to give it to?",
  str_homestory_N26dianying_90060301_144_dialog_content = "Why not have your \"lords\" <color=#FFB400>fight each other</color> for it?",
  str_homestory_N26dianying_90060301_145_dialog_content = "Anyways, the water in this well is totally murky. I don't see a \"divine image\" anywhere in here...",
  str_homestory_N26dianying_90060301_146_dialog_content = "Anyways, this chair is totally empty. I don't see a \"divine image\" anywhere on it...",
  str_homestory_N26dianying_90060301_147_dialog_content = "Anyways, the keys on this piano are spotless. I don't see a \"divine image\" anywhere on them...",
  str_homestory_N26dianying_90060301_147X1_dialog_content = "... Yao? Is that you, Yao?",
  str_homestory_N26dianying_90060301_147X2_dialog_content = "Yao? Is it really you?",
  str_homestory_N26dianying_90060301_147X3_dialog_content = "It's me, the girl next door from when we were kids! I haven't seen you in ages, Yao!",
  str_homestory_N26dianying_90060301_147X4_dialog_content = "Not since the day you left the village to find work... I thought I'd never see you again!",
  str_homestory_N26dianying_90060301_147X5_dialog_content = "Anyways, are you looking for something, by any chance?",
  str_homestory_N26dianying_90060301_147X6_dialog_content = "After we both left the village to find work... I thought I'd never see you again!",
  str_homestory_N26dianying_90060301_147X7_dialog_content = "By the way, what are you doing?",
  str_homestory_N26dianying_90060301_147X8_dialog_content = "Um, don't mention it. My two lords asked me to search for the same Heavenly Blade.",
  str_homestory_N26dianying_90060301_147X9_dialog_content = "In the end, I couldn't find anything at all...",
  str_homestory_N26dianying_90060301_147X10_dialog_content = "So you've been serving two masters all along! And after I trusted you so closely!",
  str_homestory_N26dianying_90060301_147X11_dialog_content = "L-Lord Zakura?! Wh-What are you doing here...?",
  str_homestory_N26dianying_90060301_147X12_dialog_content = "I should be asking you the very same question! Words cannot express how disappointed I am in you, my so-called \"faithful servant\"!",
  str_homestory_N26dianying_90060301_147X13_dialog_content = "L-Lord Dragonscorch?! You're here, too?!",
  str_homestory_N26dianying_90060301_147X14_dialog_content = "Uh... Wh-What's going on here?",
  str_homestory_N26dianying_90060301_147X15_dialog_content = "Uh... Wh-What's going on here?",
  str_homestory_N26dianying_90060301_147X16_dialog_content = "Uh-oh... Looks like the jig is up! Chubb!",
  str_homestory_N26dianying_90060301_147X17_dialog_content = "I was worried that this task was too great for you alone, so I arranged for someone to follow you during your quest...",
  str_homestory_N26dianying_90060301_147X18_dialog_content = "And report everything to me as it happens. It was supposed to serve as a test of your abilities.",
  str_homestory_N26dianying_90060301_147X19_dialog_content = "When I learned that your search had begun to bear fruit, I rushed over to help you find the Heavenly Blade...",
  str_homestory_N26dianying_90060301_147X20_dialog_content = "Only to hear you utter those terrible, terrible words!",
  str_homestory_N26dianying_90060301_147X21_dialog_content = "Well? What do you have to say in your defense, traitor?!",
  str_homestory_N26dianying_90060301_147X22_dialog_content = "Well... since things have come to this, I'll take responsibility for it!",
  str_homestory_N26dianying_90060301_147X23_dialog_content = "Take action, my lords! I know the rules. Today is the day I die!",
  str_homestory_N26dianying_90060301_147X24_dialog_content = "Huh?",
  str_homestory_N26dianying_90060301_147X25_dialog_content = "Kill you? What manner of joke is this?",
  str_homestory_N26dianying_90060301_147X26_dialog_content = "As a proud warrior, I would never kill an unarmed opponent.",
  str_homestory_N26dianying_90060301_147X27_dialog_content = "Despite your treachery, your remorse seems genuine... Very well, my servant. Let us go home, so that you can be punished accordingly.",
  str_homestory_N26dianying_90060301_147X28_dialog_content = "What? I was the first to arrive, so the Dragonscorch's punishment should come first!",
  str_homestory_N26dianying_90060301_147X29_dialog_content = "I say Zakura!",
  str_homestory_N26dianying_90060301_147X30_dialog_content = "I say Dragonscorch!",
  str_homestory_N26dianying_90060301_147X31_dialog_content = "Hoo-ah!",
  str_homestory_N26dianying_90060301_147X32_dialog_content = "Please, my lords... This isn't something you should be fighting over...",
  str_homestory_N26dianying_90060301_148_dialog_content = "So you've been serving two masters all along! And after I trusted you so closely!",
  str_homestory_N26dianying_90060301_149_dialog_content = "L-Lord Zakura?! Wh-What are you doing here...?",
  str_homestory_N26dianying_90060301_150_dialog_content = "I should be asking you the very same question! Words cannot express how disappointed I am in you, my so-called \"faithful servant\"!",
  str_homestory_N26dianying_90060301_151_dialog_content = "L-Lord Dragonscorch?! You're here, too?!",
  str_homestory_N26dianying_90060301_152_dialog_content = "Uh... Wh-What's going on here?",
  str_homestory_N26dianying_90060301_153_dialog_content = "Uh... Wh-What's going on here?",
  str_homestory_N26dianying_90060301_154_dialog_content = "Uh-oh... Looks like the jig is up! Chubb!",
