  str_homestory_N26dianying_90060301_156_dialog_content = "And report everything to me as it happens. It was supposed to serve as a test of your abilities.",
  str_homestory_N26dianying_90060301_157_dialog_content = "When I learned that your search had begun to bear fruit, I rushed over to help you find the Heavenly Blade...",
  str_homestory_N26dianying_90060301_158_dialog_content = "Only to hear you utter those terrible, terrible words!",
  str_homestory_N26dianying_90060301_159_dialog_content = "Well? What do you have to say in your defense, traitor?!",
  str_homestory_N26dianying_90060301_160_dialog_content = "Eh?!",
  str_homestory_N26dianying_90060301_161_dialog_content = "You dare mock me?!",
  str_homestory_N26dianying_90060301_162_dialog_content = "(They think exactly alike, don't they...)",
  str_homestory_N26dianying_90060301_163_dialog_content = "They're in perfect unison! Chubb!",
  str_homestory_N26dianying_90060301_164_dialog_content = "Lord Dragonscorch... This must be destiny. What better time to decide, once and for all, who is the strongest... Than right now!",
  str_homestory_N26dianying_90060301_165_dialog_content = "You took the words right out of my mouth. Today is the day that the Dragonscorch proves its supremacy!",
  str_homestory_N26dianying_90060301_166_dialog_content = "Hoo-ah!",
  str_homestory_N26dianying_90060301_167_dialog_content = "(Oh crap... They're about to tear each other apart! I have to do something about this...)",
  str_homestory_N26dianying_90060301_168_option_content = "Find the Heavenly Blade!",
  str_homestory_N26dianying_90060301_169_dialog_content = "Hey! Don't forget the goal of your quest!",
  str_homestory_N26dianying_90060301_170_dialog_content = "That's right! What matters most right now... Is finding the Heavenly Blade!",
  str_homestory_N26dianying_90060301_171_dialog_content = "Maybe if I take a closer look, its \"divine image\" will appear...",
  str_homestory_N26dianying_90060301_172_dialog_content = "H-Huh?!",
  str_homestory_N26dianying_90060301_173_dialog_content = "My lords! Come see, quickly!",
  str_homestory_N26dianying_90060301_174_dialog_content = "Hmm?",
  str_homestory_N26dianying_90060301_175_dialog_content = "Could it be... The Heavenly Blade?!",
  str_homestory_N26dianying_90060301_176_dialog_content = "What is this...?",
  str_homestory_N26dianying_90060301_177_dialog_content = "Why is my blade shining like this?",
  str_homestory_N26dianying_90060301_178_dialog_content = "Well, it's about time! At long last, the Heavenly Blade has been united once again!",
  str_homestory_N26dianying_90060301_179_dialog_content = "Well, it's about time! At long last, the Heavenly Blade has been united once again!",
  str_homestory_N26dianying_90060301_180_dialog_content = "You mean...",
  str_homestory_N26dianying_90060301_181_dialog_content = "That's right! The so-called \"Heavenly Blade\"... Is actually a pair of swords! And only when they're brought together, will their true power finally reveal itself.",
  str_homestory_N26dianying_90060301_182_dialog_content = "A long time ago, I had the privilege of watching two great warriors cut through scores of Eclipsites with these two blades...",
  str_homestory_N26dianying_90060301_183_dialog_content = "That's right! There are actually TWO Heavenly Blades, and their true power will only reveal itself when they're brought together!",
  str_homestory_N26dianying_90060301_184_dialog_content = "When I was still little, I saw two legendary warriors cut through an army of Eclipsites with these two blades...",
  str_homestory_N26dianying_90060301_185_dialog_content = "That was the last time the two swords were used together. After that battle, they fell into separate hands and were kept away from each other ever since.",
  str_homestory_N26dianying_90060301_186_dialog_content = "That was the last time the two swords were used together. After that battle, they fell into separate hands and were kept away from each other ever since.",
  str_homestory_N26dianying_90060301_187_dialog_content = "But now, the Heavenly Blade is whole once more!",
  str_homestory_N26dianying_90060301_188_dialog_content = "But now, the Heavenly Blade is whole once more!",
  str_homestory_N26dianying_90060301_189_dialog_content = "Th-That's right, my lords! Despite your differences, your goals are one and the same... You even think very much alike!",
  str_homestory_N26dianying_90060301_190_dialog_content = "Instead of fighting amongst yourselves, why not combine your forces and save the world together?",
  str_homestory_N26dianying_90060301_191_dialog_content = "Hmm...",
  str_homestory_N26dianying_90060301_192_dialog_content = "Er...",
  str_homestory_N26dianying_90060301_193_dialog_content = "The servant makes a valid point... After all, we both seek the power of the Heavenly Blade.",
  str_homestory_N26dianying_90060301_194_dialog_content = "And if we combine our forces, we would still be the leaders of the world's most powerful faction.",
  str_homestory_N26dianying_90060301_195_dialog_content = "As for you, our \"faithful\" servant...",
  str_homestory_N26dianying_90060301_196_dialog_content = "Uh-oh...",
  str_homestory_N26dianying_90060301_197_dialog_content = "You have proven your worth, and the Zakura will forever be in your debt!",
  str_homestory_N26dianying_90060301_198_dialog_content = "The Dragonscorch owes much to your diligent efforts, as well!",
  str_homestory_N26dianying_90060301_199_dialog_content = "<size=45>My lords!</size>",
  str_homestory_N26dianying_90060301_200_dialog_content = "Heheheh... And so, a new legend was born!",
  str_homestory_N26dianying_90060301_201_dialog_content = "Heehee! And so, a new legend was born!",
  str_homestory_N26dianying_90060301_202_dialog_content = "\"In the end, the Zakura and Dragonscorch set aside their differences and merged into one powerful army.\"",
  str_homestory_N26dianying_90060301_203_dialog_content = "\"With their combined strength, as well as the power of the Heavenly Blade, the world was blessed with peace once more.\"",
  str_homestory_N26dianying_90060301_204_dialog_content = "\"In the end, the Zakura and Dragonscorch set aside their differences and merged into one powerful army.\"",
  str_homestory_N26dianying_90060301_205_dialog_content = "\"With their combined strength, as well as the power of the Heavenly Blade, the world was blessed with peace once more.\"",
  str_homestory_N26dianying_90060301_206_option_content = "Try to make amends!",
  str_homestory_N26dianying_90060301_207_dialog_content = "You know those two better than anyone else! Go work things out between them!",
  str_homestory_N26dianying_90060301_208_dialog_content = "That's right! As their servant, I'm the only one who can settle their differences!",
  str_homestory_N26dianying_90060301_209_dialog_content = "My lords, if I may speak? Despite your differences, your goals are the same... You even think very much alike!",
