  str_homestory_N26dianying_90060301_228_dialog_content = "No, wait... It's my fault that things turned out this way. I have to take responsibility for my actions...",
  str_homestory_N26dianying_90060301_229_dialog_content = "My lords! I'm the one to blame for all of this! If you're going to kill someone, kill me!",
  str_homestory_N26dianying_90060301_230_dialog_content = "Huh?",
