  str_homestory_N26dianying_90060301_244_dialog_content = "What happened?",
  str_homestory_N26dianying_90060301_245_dialog_content = "The village was ransacked by a gang of bandits just yesterday.",
  str_homestory_N26dianying_90060301_246_dialog_content = "The village was ransacked by a gang of bandits just yesterday.",
  str_homestory_N26dianying_90060301_247_dialog_content = "They took everything! My weapons, my money, the deed to my house... They even took my favorite mechanical weapon rack!",
  str_homestory_N26dianying_90060301_248_dialog_content = "They took everything! My Holy Water Shells, my money... They even took my favorite mechanical weapon rack!",
  str_homestory_N26dianying_90060301_249_dialog_content = "I have nothing left!",
  str_homestory_N26dianying_90060301_250_dialog_content = "I have nothing left!",
  str_homestory_N26dianying_90060301_251_dialog_content = "N-Nothing at all?!",
  str_homestory_N26dianying_90060301_252_dialog_content = "I'm sorry, I know this probably isn't the right time to ask... But have you heard of the legendary Heavenly Blade?",
